-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 06 — Permission catalogue, role matrix, triggers
-- ═══════════════════════════════════════════════════════════════════════════

-- Migration 04 applies `force row level security` to all 45 tables, and these
-- two carry a select policy and nothing else. FORCE is the part that matters:
-- ordinary RLS exempts a table's owner, FORCE does not, so these seed inserts
-- are refused for anyone lacking BYPASSRLS — including whoever is applying the
-- migration.
--
--   ERROR: new row violates row-level security policy for table "permissions"
--
-- Superusers bypass RLS unconditionally, so a local PostgreSQL never showed
-- it. Whether a hosted project does depends on whether its role happens to
-- carry BYPASSRLS, which is not a thing to build a schema on.
--
-- FORCE is lifted for the length of the seed and restored immediately. Both
-- statements are inside the migration's transaction, so there is no window in
-- which the tables are deployed unprotected.
--
-- These two are a fixed catalogue, not tenant data: every organisation reads
-- the same rows, which is why a select policy is all they ever needed.
alter table public.permissions      no force row level security;
alter table public.role_permissions no force row level security;

insert into public.permissions (key, category, description) values
  ('view_performance',        'Performance',    'View business performance dashboards and metrics'),
  ('view_financial_data',     'Performance',    'View revenue, cost, margin and cash figures'),
  ('view_sales_data',         'Performance',    'View sales records, customers and pipeline value'),
  ('view_operations_data',    'Performance',    'View operational measures such as delivery and utilisation'),
  ('view_intelligence',       'Intelligence',   'View AI DigitalTwin® findings, events and insights'),
  ('view_market_intelligence','Intelligence',   'View external market signals'),
  ('view_competitors',        'Intelligence',   'View tracked competitors and their activity'),
  ('view_opportunities',      'Opportunities',  'View the opportunity pipeline and radar'),
  ('assign_opportunities',    'Opportunities',  'Assign opportunities to colleagues'),
  ('manage_opportunities',    'Opportunities',  'Create, edit and progress opportunities'),
  ('view_recommendations',    'Strategy',       'View AI recommendations'),
  ('manage_recommendations',  'Strategy',       'Accept, dismiss and progress recommendations'),
  ('view_goals',              'Strategy',       'View goals and strategic initiatives'),
  ('manage_goals',            'Strategy',       'Create and edit goals and initiatives'),
  ('view_risks',              'Risk',           'View the risk register and risk dashboard'),
  ('manage_risks',            'Risk',           'Raise, reassess and close risks'),
  ('view_alerts',             'Risk',           'View alerts'),
  ('manage_alerts',           'Risk',           'Acknowledge, assign, snooze and dismiss alerts'),
  ('view_data_sources',       'Data',           'View connected sources, imports and data health'),
  ('import_data',             'Data',           'Upload and import business data'),
  ('manage_integrations',     'Data',           'Create and configure data connections'),
  ('manage_metrics',          'Data',           'Define metrics and health-score weighting'),
  ('manage_competitors',      'Intelligence',   'Add and edit tracked competitors'),
  ('manage_radar',            'Intelligence',   'Configure market sources and radar scoring'),
  ('generate_reports',        'Reporting',      'Generate and export reports'),
  ('use_ai_assistant',        'Intelligence',   'Ask the Amryn AI Assistant questions'),
  ('view_audit_log',          'Administration', 'Read the organisation audit trail'),
  ('manage_users',            'Administration', 'Invite, edit and remove members and permissions'),
  ('manage_organisation',     'Administration', 'Edit the organisation, regions, branches and departments'),
  ('manage_billing',          'Administration', 'View and change the subscription and billing details');

-- ── role matrix ───────────────────────────────────────────────────────────
-- Reach widens down the list; scope (which branches a member sees) is a
-- separate axis, applied by RLS on top of these grants.

do $$
declare
  everything text[] := array(select key from public.permissions order by key);

  viewer text[] := array[
    'view_performance','view_intelligence','view_market_intelligence','view_competitors',
    'view_opportunities','view_recommendations','view_goals','view_alerts','use_ai_assistant'
  ];

  department_manager text[] := viewer || array[
    'view_sales_data','view_operations_data','view_risks','view_data_sources',
    'manage_goals','manage_alerts','generate_reports'
  ];

  branch_manager text[] := department_manager || array[
    'view_financial_data','manage_opportunities','manage_recommendations','manage_risks','import_data'
  ];

  regional_manager text[] := branch_manager || array[
    'assign_opportunities','view_audit_log'
  ];

  analyst text[] := array[
    'view_performance','view_financial_data','view_sales_data','view_operations_data',
    'view_intelligence','view_market_intelligence','view_competitors','view_opportunities',
    'view_recommendations','view_goals','view_risks','view_alerts','view_data_sources',
    'import_data','manage_metrics','generate_reports','use_ai_assistant'
  ];

  -- The executive view is the whole business, minus the plumbing that
  -- administrators and analysts own.
  executive text[] := regional_manager || array[
    'manage_competitors','manage_radar','manage_users'
  ];
begin
  insert into public.role_permissions (role, permission_key)
  select 'super_admin'::public.org_role, unnest(everything)
  union all select 'org_admin', unnest(everything)
  union all select 'executive', unnest(executive)
  union all select 'regional_manager', unnest(regional_manager)
  union all select 'branch_manager', unnest(branch_manager)
  union all select 'department_manager', unnest(department_manager)
  union all select 'analyst', unnest(analyst)
  union all select 'viewer', unnest(viewer)
  on conflict do nothing;
end;
$$;

-- Protection restored before anything else runs.
alter table public.permissions      force row level security;
alter table public.role_permissions force row level security;

-- ═══════════════════════════════════════════════════════════════════════════
-- Triggers
-- ═══════════════════════════════════════════════════════════════════════════

create or replace function amryn.touch_updated_at()
returns trigger
language plpgsql
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'organisations','user_profiles','regions','branches','departments',
    'organisation_members','subscriptions','data_sources','data_connections',
    'business_metrics','competitors','opportunities','goals',
    'strategic_initiatives','ai_recommendations','risks','ai_conversations'
  ]
  loop
    execute format(
      'create trigger %I before update on public.%I for each row execute function amryn.touch_updated_at()',
      t || '_touch', t
    );
  end loop;
end;
$$;

-- Mirror new auth users into user_profiles so the app always has a profile to
-- render, without a first-login write path that could fail.
create or replace function amryn.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.user_profiles (id, email, full_name, avatar_url)
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url'
  )
  on conflict (id) do update
    set email = excluded.email,
        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);
  return new;
end;
$$;

-- Guarded, because creating a trigger requires owning the table and on a
-- hosted Supabase project auth.users belongs to supabase_auth_admin rather
-- than the role applying this file. Unguarded, this one statement failed the
-- entire migration — taking the permission catalogue, the role matrix and
-- create_organisation down with it, and leaving a database that looked like
-- the migrations had never run.
--
-- Where the trigger cannot be installed, public.ensure_user_profile() in
-- migration 10 does the same work on first sign-in instead.
do $$
begin
  create trigger on_auth_user_created
    after insert on auth.users
    for each row execute function amryn.handle_new_user();
exception
  when insufficient_privilege then
    raise notice 'not permitted to add a trigger to auth.users; profiles are created on first sign-in instead';
  when duplicate_object then
    raise notice 'profile trigger already present';
end;
$$;

-- Risk severity is derived from likelihood × impact, but stored, so that a
-- later change to the scale does not silently rewrite history.
create or replace function amryn.derive_risk_severity()
returns trigger
language plpgsql
as $$
declare
  product integer := new.likelihood * new.impact;
begin
  new.severity := case
    when product >= 20 then 'critical'::public.priority_level
    when product >= 12 then 'high'::public.priority_level
    when product >= 6  then 'medium'::public.priority_level
    else 'low'::public.priority_level
  end;
  return new;
end;
$$;

create trigger risks_derive_severity
  before insert or update of likelihood, impact on public.risks
  for each row execute function amryn.derive_risk_severity();

-- ── organisation bootstrap ────────────────────────────────────────────────
-- Creating an organisation from the app is a single call: it must also create
-- the caller's membership, the subscription and the default weighting, or none
-- of it. SECURITY DEFINER because the caller is not yet a member of the
-- organisation whose rows are being written.

create or replace function public.create_organisation(
  p_name text,
  p_slug text,
  p_industry text default null,
  p_country_code char(2) default 'ZA',
  p_currency_code char(3) default 'ZAR'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  new_org uuid;
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  insert into public.organisations (name, slug, industry, country_code, currency_code)
  values (p_name, lower(p_slug), p_industry, upper(p_country_code), upper(p_currency_code))
  returning id into new_org;

  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)
  values (new_org, uid, 'org_admin', 'active', 'organisation');

  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)
  values (new_org, 'starter', 'trialing', now() + interval '30 days');

  insert into public.health_score_weights (organisation_id, category, weight) values
    (new_org, 'financial',   0.25),
    (new_org, 'operational', 0.20),
    (new_org, 'sales',       0.20),
    (new_org, 'growth',      0.15),
    (new_org, 'customer',    0.10),
    (new_org, 'strategic',   0.10);

  insert into public.opportunity_score_weights (organisation_id) values (new_org);

  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);

  return new_org;
end;
$$;

revoke all on function public.create_organisation(text, text, text, char, char) from public, anon;
grant execute on function public.create_organisation(text, text, text, char, char) to authenticated;

-- Health-score weights must sum to 1 for the score to be a true weighted mean.
create or replace function amryn.assert_health_weights_sum()
returns trigger
language plpgsql
as $$
declare
  total numeric;
  org uuid := coalesce(new.organisation_id, old.organisation_id);
begin
  select sum(weight) into total
    from public.health_score_weights
   where organisation_id = org;

  if total is not null and abs(total - 1) > 0.001 then
    raise exception 'health score weights for organisation % sum to %, expected 1', org, total;
  end if;
  return null;
end;
$$;

create constraint trigger health_weights_sum_to_one
  after insert or update or delete on public.health_score_weights
  deferrable initially deferred
  for each row execute function amryn.assert_health_weights_sum();

-- PostgREST answers from a cached copy of the schema and is not told by
-- applying SQL. Without this, everything above exists and stays invisible to
-- the application — which reads exactly like a migration that never ran.
notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830080000_07_sector_policy.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830080000_07_sector_policy.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 07 — Sector policy belongs to the customer, not to the platform
--
-- Migration 03 defaulted market scanning to the private sector alone and the
-- recommendation layer refused to surface tenders at all. That conflated two
-- different things:
--
--   · Amryn's own commercial posture — the company does not take on
--     government-sector business. That is a fact about who Amryn sells to,
--     and it belongs in the company's positioning, not in a WHERE clause.
--
--   · What an Amryn customer should be shown. Customers are private
--     businesses, and a municipal supply tender is ordinary revenue to a
--     wholesaler. Filtering it out withheld real money from the people
--     paying for the product.
--
-- So sector scope becomes an explicit, per-organisation setting. The default
-- is to surface everything and let relevance and strategic alignment decide
-- what ranks — which is what those factors are for. An organisation that does
-- not pursue public-sector work narrows the setting once, and the radar
-- honours it everywhere.
-- ═══════════════════════════════════════════════════════════════════════════

-- A tender is its own kind of opportunity: a defined scope, a published
-- deadline and a competitive submission. Modelling it as 'market_expansion'
-- lost the shape that makes it actionable.
alter type public.opportunity_kind add value if not exists 'tender';

-- ── per-organisation sector scope ─────────────────────────────────────────
-- Which sectors this organisation wants its radar to surface. Defaults to all
-- of them: an opportunity is filtered out only because a customer chose to
-- filter it, never because the platform decided on their behalf.

alter table public.organisations
  add column if not exists sector_scope public.market_sector[]
    not null default '{private,public,mixed,unknown}';

comment on column public.organisations.sector_scope is
  'Sectors the AI OpportunityRadar® may surface for this organisation. Set by the customer. Amryn''s own commercial posture is not encoded here.';

alter table public.organisations
  add constraint sector_scope_not_empty check (cardinality(sector_scope) > 0);

-- Existing market sources were seeded private-only by the previous default.
-- Widen them to match the new posture; a customer narrows from here.
alter table public.market_sources
  alter column sector_policy set default '{private,public,mixed,unknown}';

update public.market_sources
   set sector_policy = '{private,public,mixed,unknown}'
 where sector_policy = '{private}';

-- ── honouring the setting ─────────────────────────────────────────────────
-- Enforced in the database rather than only in the query layer, so a report,
-- an export and the assistant all see the same set. A row outside the
-- organisation's chosen scope is simply not selectable.

create or replace function amryn.sector_in_scope(p_org uuid, p_sector public.market_sector)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select p_sector = any (o.sector_scope) from public.organisations o where o.id = p_org),
    false
  );
$$;

grant execute on function amryn.sector_in_scope(uuid, public.market_sector) to authenticated;

drop policy if exists opportunities_read on public.opportunities;
create policy opportunities_read on public.opportunities
  for select to authenticated
  using (
    amryn.has_permission(organisation_id, 'view_opportunities')
    and amryn.can_see_branch(organisation_id, branch_id)
    and amryn.sector_in_scope(organisation_id, sector)
  );

drop policy if exists market_signals_read on public.market_signals;
create policy market_signals_read on public.market_signals
  for select to authenticated
  using (
    amryn.has_permission(organisation_id, 'view_market_intelligence')
    and amryn.sector_in_scope(organisation_id, sector)
  );

-- PostgREST answers from a cached copy of the schema and is not told by
-- applying SQL. Without this, everything above exists and stays invisible to
-- the application — which reads exactly like a migration that never ran.
notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830190000_08_organisation_bootstrap_rpc.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830190000_08_organisation_bootstrap_rpc.sql'; end $setup$;

-- ── organisation bootstrap, made reachable ────────────────────────────────
--
-- Symptom this fixes, seen on the live deployment at /onboarding:
--
--   Could not find the function public.create_organisation(p_country_code,
--   p_currency_code, p_industry, p_name, p_slug) in the schema cache
--
-- PostgREST resolves a remote call against a cache of the schema, not against
-- the schema. Three separate things produce that one message, and the reader
-- cannot tell them apart:
--
--   1. The function is genuinely absent — migration 06 was never applied.
--   2. It exists, but PostgREST last built its cache before it did. Applying
--      migrations through the SQL editor does not reload that cache, so a
--      correct database serves a stale answer indefinitely.
--   3. It exists, but the caller's arguments cannot be coerced to its
--      parameter types, so no candidate matches.
--
-- This migration settles all three, and is safe to run whether or not 06 was.
--
-- On (3): the parameters were char(2) and char(3). A blank-padded fixed-width
-- type is a poor thing to expose over an interface that sends everything as
-- JSON text, and it buys nothing here — the columns are still char(2)/char(3)
-- with their own check constraints, so the storage guarantee is unchanged.
-- The parameters become text, and the function validates them itself so a bad
-- value is a sentence rather than a silent truncation.
--
-- A type change cannot be made with `create or replace`: Postgres treats a
-- different parameter type as a different function and would leave both in
-- place. Two candidates with identical argument names is worse than none —
-- PostgREST then fails as ambiguous. So both signatures are dropped first.

drop function if exists public.create_organisation(text, text, text, char, char);
drop function if exists public.create_organisation(text, text, text, text, text);

create function public.create_organisation(
  p_name text,
  p_slug text,
  p_industry text default null,
  p_country_code text default 'ZA',
  p_currency_code text default 'ZAR'
)
returns uuid
language plpgsql
security definer
-- SECURITY DEFINER because the caller is not yet a member of the organisation
-- whose rows are being written. search_path is pinned so the elevated body
-- cannot be redirected to a caller-controlled schema.
set search_path = public, pg_temp
as $$
declare
  new_org  uuid;
  uid      uuid := auth.uid();
  country  text := upper(btrim(coalesce(p_country_code, 'ZA')));
  currency text := upper(btrim(coalesce(p_currency_code, 'ZAR')));
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  -- Validated here rather than left to the column cast. char(2) silently
  -- truncates anything longer, so 'ZAF' would have been stored as 'ZA' and
  -- nobody would have been told.
  if length(country) <> 2 then
    raise exception 'country code must be two letters, got %', country
      using errcode = '22023';
  end if;

  if length(currency) <> 3 then
    raise exception 'currency code must be three letters, got %', currency
      using errcode = '22023';
  end if;

  insert into public.organisations (name, slug, industry, country_code, currency_code)
  values (p_name, lower(p_slug), p_industry, country, currency)
  returning id into new_org;

  insert into public.organisation_members (organisation_id, user_id, role, status, scope_kind)
  values (new_org, uid, 'org_admin', 'active', 'organisation');

  insert into public.subscriptions (organisation_id, plan, status, trial_ends_at)
  values (new_org, 'starter', 'trialing', now() + interval '30 days');

  insert into public.health_score_weights (organisation_id, category, weight) values
    (new_org, 'financial',   0.25),
    (new_org, 'operational', 0.20),
    (new_org, 'sales',       0.20),
    (new_org, 'growth',      0.15),
    (new_org, 'customer',    0.10),
    (new_org, 'strategic',   0.10);

  insert into public.opportunity_score_weights (organisation_id) values (new_org);

  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values (new_org, uid, 'organisation.created', 'organisation', new_org::text, p_name);

  return new_org;
end;
$$;

-- anon must never reach this: it writes an organisation and an admin
-- membership, and it runs as its owner.
revoke all on function public.create_organisation(text, text, text, text, text) from public, anon;
grant execute on function public.create_organisation(text, text, text, text, text) to authenticated;

-- Cause (2). Without this the function above exists and stays invisible over
-- the API until something else happens to reload the cache.
notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830200000_09_default_privileges.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830200000_09_default_privileges.sql'; end $setup$;

-- ── privileges for tables added later ─────────────────────────────────────
--
-- Migration 05 grants `authenticated` its table privileges with
-- `grant ... on all tables in schema public`. That phrasing is a snapshot: it
-- covers the tables existing at the moment it runs, and says nothing about any
-- added afterwards. A table created by a future migration would therefore be
-- unreachable by every signed-in user, and PostgREST would report it as
-- missing from the schema cache rather than as a privilege problem — which is
-- a long way from the cause.
--
-- Default privileges close that, so the grant applies to what does not exist
-- yet.
--
-- Deliberately nothing for `anon`. It holds no privilege on these tables and
-- should not: every one of the 45 policies targets `authenticated`, so Row
-- Level Security alone would already return an anonymous caller nothing, and
-- withholding the grant as well means a policy misconfigured tomorrow still
-- cannot leak to an anonymous request. 10_rls_isolation_test.sql asserts that
-- second wall is standing.

alter default privileges in schema public
  grant select, insert, update, delete on tables to authenticated;

alter default privileges in schema public
  grant usage, select on sequences to authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260830210000_10_profile_without_auth_trigger.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260830210000_10_profile_without_auth_trigger.sql'; end $setup$;

-- ── surviving a trigger that cannot be created ────────────────────────────
--
-- Migration 06 ends with:
--
--   create trigger on_auth_user_created after insert on auth.users ...
--
-- Creating a trigger requires ownership of the table, and on a hosted Supabase
-- project auth.users belongs to supabase_auth_admin, not to the role the SQL
-- editor runs as. Whether that succeeds depends on the vintage of the project;
-- on the ones where it does not, it fails with
--
--   ERROR: 42501: must be owner of relation users
--
-- and because the editor runs each script in a transaction, the whole of
-- migration 06 rolls back — the permission catalogue, the role matrix and
-- create_organisation with it. The database is then left with every table and
-- policy in place and none of its seed data, which reads exactly like
-- migrations that were never applied.
--
-- A local PostgreSQL owns everything, so the suite never saw it.
--
-- Rather than depend on knowing which kind of project this is, the trigger
-- becomes optional and its work is made reachable another way.

-- 1. Never let this be the statement that fails a migration.
do $$
begin
  create trigger on_auth_user_created
    after insert on auth.users
    for each row execute function amryn.handle_new_user();
  raise notice 'profile trigger installed on auth.users';
exception
  when insufficient_privilege then
    raise notice 'not permitted to add a trigger to auth.users on this project; profiles are created on first sign-in instead';
  when duplicate_object then
    raise notice 'profile trigger already present';
end;
$$;

-- 2. The first-login write path the trigger existed to avoid needing.
--
-- SECURITY DEFINER so it can read auth.users, which the caller cannot. It acts
-- only on auth.uid(), so a caller can create a profile for themselves and for
-- nobody else — there is no parameter to point at another user.
create or replace function public.ensure_user_profile()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    return;
  end if;

  insert into public.user_profiles (id, email, full_name, avatar_url)
  select
    u.id,
    u.email,
    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
    u.raw_user_meta_data ->> 'avatar_url'
  from auth.users u
  where u.id = uid
  on conflict (id) do update
    set email = excluded.email,
        full_name = coalesce(public.user_profiles.full_name, excluded.full_name);
end;
$$;

revoke all on function public.ensure_user_profile() from public, anon;
grant execute on function public.ensure_user_profile() to authenticated;

-- 3. Anyone who signed up while the trigger was absent has no profile. Backfill
-- them, so this migration repairs the accounts it was too late to prevent.
insert into public.user_profiles (id, email, full_name, avatar_url)
select
  u.id,
  u.email,
  coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
  u.raw_user_meta_data ->> 'avatar_url'
from auth.users u
on conflict (id) do nothing;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260831090000_11_invitations.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260831090000_11_invitations.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 11 — Invitations
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Until now every person who signed up got an organisation of their own, and
-- there was no way into anyone else's. The members screen already rendered an
-- `invited` status and nothing ever wrote one.
--
-- The obvious implementation does not work: organisation_members.user_id
-- references auth.users and is not null, so a membership cannot exist for
-- somebody who has not signed up yet — which is exactly who an invitation is
-- for. So an invitation is its own record, and becomes a membership when it is
-- accepted.
--
-- The link is the credential, so it is treated as one. Only a SHA-256 hash of
-- the token is stored: the database never holds anything that grants access,
-- and a leaked backup does not let anyone in. The raw token exists once, in the
-- response that creates it, and is shown to the person who will send it on.

create table public.organisation_invitations (
  id              uuid primary key default gen_random_uuid(),
  organisation_id uuid not null references public.organisations (id) on delete cascade,
  -- citext, so an invitation to Someone@Example.com is accepted by
  -- someone@example.com. Case-sensitivity here would be a support burden and
  -- protects nothing.
  email           citext not null,
  role            public.org_role not null default 'viewer',
  scope_kind      public.scope_kind not null default 'organisation',
  scope_ids       uuid[] not null default '{}',
  -- Never the token itself.
  token_hash      text not null unique,
  invited_by      uuid references auth.users (id) on delete set null,
  expires_at      timestamptz not null default now() + interval '14 days',
  accepted_at     timestamptz,
  accepted_by     uuid references auth.users (id) on delete set null,
  revoked_at      timestamptz,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  constraint scope_ids_match_kind check (
    (scope_kind = 'organisation' and cardinality(scope_ids) = 0)
    or (scope_kind <> 'organisation' and cardinality(scope_ids) > 0)
  ),
  -- An invitation is either open, accepted or revoked. Recording both an
  -- acceptance and a revocation would leave no answer to "did they get in".
  constraint not_both_accepted_and_revoked check (
    accepted_at is null or revoked_at is null
  )
);

-- One open invitation per address per organisation. A partial index rather than
-- a plain unique constraint, so the same person can be re-invited after an
-- invitation is revoked or expires.
create unique index organisation_invitations_open_email
  on public.organisation_invitations (organisation_id, email)
  where accepted_at is null and revoked_at is null;

create index organisation_invitations_org on public.organisation_invitations (organisation_id);

create trigger organisation_invitations_touch
  before update on public.organisation_invitations
  for each row execute function amryn.touch_updated_at();

-- ── who may see and write them ────────────────────────────────────────────
alter table public.organisation_invitations enable row level security;
alter table public.organisation_invitations force row level security;

-- Reading an invitation reveals who is being brought into the business, so it
-- is limited to the people who manage members — not every colleague.
create policy organisation_invitations_read on public.organisation_invitations
  for select to authenticated
  using (amryn.has_permission(organisation_id, 'manage_users'));

create policy organisation_invitations_write on public.organisation_invitations
  for insert to authenticated
  with check (amryn.has_permission(organisation_id, 'manage_users'));

-- Update covers revoking. Acceptance does not come through here: the invitee
-- is not a member yet and no policy would let them touch the row, which is why
-- accept_invitation() runs as its owner.
create policy organisation_invitations_update on public.organisation_invitations
  for update to authenticated
  using (amryn.has_permission(organisation_id, 'manage_users'))
  with check (amryn.has_permission(organisation_id, 'manage_users'));

grant select, insert, update on public.organisation_invitations to authenticated;

-- ── looking at an invitation before accepting it ──────────────────────────
--
-- The invitee cannot read the row — they are not a member of anything yet — so
-- this reads it for them and returns only what the page needs to say: which
-- organisation, which role, and whether the link is still good. Not who else
-- is invited, and not the token.
--
-- Takes the raw token, so possession of the link is the whole authorisation.
create or replace function public.invitation_preview(p_token text)
returns table (
  organisation_name text,
  role              public.org_role,
  email             text,
  state             text
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');
  -- Not named `found`: that is PL/pgSQL's own boolean, and shadowing it makes
  -- `if not found` a type error rather than the check it looks like.
  invite record;
begin
  select i.*, o.name as org_name
    into invite
    from public.organisation_invitations i
    join public.organisations o on o.id = i.organisation_id
   where i.token_hash = hashed;

  if invite.id is null then
    -- Deliberately indistinguishable from an expired one on the caller's side:
    -- a separate "no such invitation" would make this a way to test tokens.
    return query select null::text, null::public.org_role, null::text, 'invalid'::text;
    return;
  end if;

  return query select
    invite.org_name::text,
    invite.role,
    invite.email::text,
    case
      when invite.revoked_at is not null then 'revoked'
      when invite.accepted_at is not null then 'accepted'
      when invite.expires_at <= now() then 'expired'
      else 'open'
    end;
end;
$$;

revoke all on function public.invitation_preview(text) from public;
-- anon may call it: someone following an invitation link has usually not
-- signed in yet, and being told what they are being invited to is the point.
grant execute on function public.invitation_preview(text) to anon, authenticated;

-- ── accepting ─────────────────────────────────────────────────────────────
--
-- SECURITY DEFINER because the caller is, by definition, not yet a member of
-- the organisation whose membership row is about to be written — the same
-- reason create_organisation() runs this way.
--
-- The membership is created with the role and scope recorded on the
-- invitation, never with anything the caller sends. There is no parameter here
-- but the token.
create or replace function public.accept_invitation(p_token text)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid        uuid := auth.uid();
  user_email citext;
  invite     public.organisation_invitations;
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  select u.email into user_email from auth.users u where u.id = uid;

  select * into invite
    from public.organisation_invitations
   where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex')
     for update;

  if not found then
    raise exception 'this invitation link is not valid' using errcode = '22023';
  end if;

  if invite.revoked_at is not null then
    raise exception 'this invitation has been withdrawn' using errcode = '22023';
  end if;

  if invite.expires_at <= now() then
    raise exception 'this invitation has expired' using errcode = '22023';
  end if;

  -- Bound to the address it was sent to. Holding the link is not enough:
  -- a forwarded invitation would otherwise hand a stranger access to the
  -- company's data under someone else's name.
  if user_email is null or user_email <> invite.email then
    raise exception 'this invitation was sent to a different email address'
      using errcode = '42501';
  end if;

  -- Already accepted is only an error if somebody else accepted it. For the
  -- same person it is a repeated click, and the answer is where they were
  -- going anyway.
  if invite.accepted_at is not null then
    if invite.accepted_by = uid then
      return invite.organisation_id;
    end if;
    raise exception 'this invitation has already been used' using errcode = '22023';
  end if;

  insert into public.organisation_members
    (organisation_id, user_id, role, status, scope_kind, scope_ids, invited_by, invited_at)
  values
    (invite.organisation_id, uid, invite.role, 'active', invite.scope_kind,
     invite.scope_ids, invite.invited_by, invite.created_at)
  on conflict (organisation_id, user_id) do update
    set status = 'active';

  update public.organisation_invitations
     set accepted_at = now(), accepted_by = uid
   where id = invite.id;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values
    (invite.organisation_id, uid, 'member.joined', 'organisation_member', uid::text,
     invite.email || ' accepted an invitation as ' || invite.role);

  return invite.organisation_id;
end;
$$;

revoke all on function public.accept_invitation(text) from public, anon;
grant execute on function public.accept_invitation(text) to authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260831120000_12_rate_limits.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260831120000_12_rate_limits.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 12 — Rate limiting
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Sign-in, sign-up, organisation creation and invitations had no limit on how
-- often they could be attempted. That is a credential-stuffing surface on the
-- first two and, on the last, a way for one administrator to issue unbounded
-- invitations.
--
-- In the database rather than in memory, because the application runs as
-- serverless functions: an in-memory counter is per-instance, resets whenever
-- one is recycled, and counts nothing at all once there is more than one.
--
-- ── what is stored ────────────────────────────────────────────────────────
-- Only a hash. The thing being limited is an email address or an IP address,
-- and both are personal information under POPIA — keeping either in readable
-- form would mean a table of who tried to sign in and from where, retained for
-- no purpose the person consented to. A SHA-256 of the identifier answers
-- "has this one been seen too often" without recording whose it is.

create table public.rate_limits (
  -- The hash is the identity of the bucket; there is nothing else to key on.
  bucket      text primary key,
  attempts    integer not null default 0,
  -- When the current window began. A window is a fixed period from the first
  -- attempt, not a sliding one: simpler to reason about, and the difference
  -- does not matter at the resolution of a login form.
  window_start timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);

create index rate_limits_window_start on public.rate_limits (window_start);

-- Locked down completely. Nothing reads or writes this except the function
-- below, which runs as its owner: the counts are not the application's
-- business, and a client that could read them could enumerate activity.
alter table public.rate_limits enable row level security;
alter table public.rate_limits force row level security;
revoke all on public.rate_limits from public, anon, authenticated;

-- ── the check ─────────────────────────────────────────────────────────────
--
-- Returns true when the attempt is allowed. Atomic: the insert-on-conflict is
-- a single statement, so two requests arriving together cannot both read a
-- count of four and both decide they are the fifth.
--
-- Callable by anon, because sign-in and sign-up are attempted before anyone is
-- authenticated. It takes an already-hashed key, so the raw address never
-- travels to the database and never appears in a query log.
create or replace function public.check_rate_limit(
  p_bucket   text,
  p_max      integer,
  p_window   interval
)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  current_attempts integer;
begin
  if p_bucket is null or length(p_bucket) = 0 then
    -- Nothing to key on. Allowing it is the right failure: a rate limiter that
    -- refuses when it cannot identify the caller locks everyone out.
    return true;
  end if;

  insert into public.rate_limits (bucket, attempts, window_start, updated_at)
  values (p_bucket, 1, now(), now())
  on conflict (bucket) do update
    set
      -- Past the window, the count starts again rather than accumulating
      -- forever.
      attempts = case
        when public.rate_limits.window_start < now() - p_window then 1
        else public.rate_limits.attempts + 1
      end,
      window_start = case
        when public.rate_limits.window_start < now() - p_window then now()
        else public.rate_limits.window_start
      end,
      updated_at = now()
  returning attempts into current_attempts;

  return current_attempts <= p_max;
end;
$$;

revoke all on function public.check_rate_limit(text, integer, interval) from public;
grant execute on function public.check_rate_limit(text, integer, interval) to anon, authenticated;

-- ── housekeeping ──────────────────────────────────────────────────────────
--
-- Rows outlive their usefulness the moment their window closes. Keeping them
-- would turn a counter into a log of attempts, which is the thing this table
-- was designed not to be.
create or replace function public.prune_rate_limits()
returns integer
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  removed integer;
begin
  delete from public.rate_limits where window_start < now() - interval '1 day';
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke all on function public.prune_rate_limits() from public, anon, authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260831140000_13_consent_and_data_rights.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260831140000_13_consent_and_data_rights.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 13 — Consent, and the right to ask what is held
-- ═══════════════════════════════════════════════════════════════════════════
--
-- POPIA (Act 4 of 2013) requires that processing rest on a lawful basis, that
-- the data subject be able to establish what is held about them, and that they
-- can ask for it to be corrected or destroyed. Two things follow that the
-- schema did not have.
--
-- ── consent, with a date ──────────────────────────────────────────────────
-- "They accepted the terms" is not a fact unless it is written down. The
-- version matters as much as the timestamp: terms change, and consent to one
-- wording is not consent to a later one, so both are recorded and a change of
-- version is visible as an absence rather than assumed away.

alter table public.user_profiles
  add column terms_accepted_at timestamptz,
  add column terms_version     text,
  add column privacy_accepted_at timestamptz,
  add column privacy_version   text;

comment on column public.user_profiles.terms_accepted_at is
  'When this person accepted the terms of service. Null means they have not.';
comment on column public.user_profiles.terms_version is
  'Which wording they accepted. Consent to one version is not consent to the next.';

-- An organisation is a separate consenting party: its administrator agrees to
-- the data processing addendum on the organisation''s behalf, which is a
-- different act from that person accepting the terms as an individual.
alter table public.organisations
  add column dpa_accepted_at timestamptz,
  add column dpa_version     text,
  add column dpa_accepted_by uuid references auth.users (id) on delete set null;

comment on column public.organisations.dpa_accepted_at is
  'When an administrator accepted the data processing addendum for this organisation.';

-- ── the right to ask ──────────────────────────────────────────────────────
--
-- A request is recorded rather than acted on immediately. Export and erasure
-- both need judgement — an organisation''s records are not one member''s to
-- delete, and a request from an administrator may implicate colleagues — so
-- this creates an auditable obligation with a clock on it, which is what the
-- Act actually asks for.

create type public.data_request_kind as enum ('export', 'deletion', 'correction');
create type public.data_request_status as enum ('received', 'in_progress', 'completed', 'refused');

create table public.data_requests (
  id             uuid primary key default gen_random_uuid(),
  user_id        uuid not null references auth.users (id) on delete cascade,
  kind           public.data_request_kind not null,
  status         public.data_request_status not null default 'received',
  -- What the person said, in their words. Useful for a correction request,
  -- where the substance is the point.
  note           text check (note is null or length(note) <= 2000),
  -- What was done, for the audit trail. Never shown to the requester as-is.
  resolution     text,
  requested_at   timestamptz not null default now(),
  responded_at   timestamptz,
  created_at     timestamptz not null default now(),
  updated_at     timestamptz not null default now()
);

create index data_requests_user on public.data_requests (user_id);
create index data_requests_open on public.data_requests (status) where status in ('received', 'in_progress');

create trigger data_requests_touch
  before update on public.data_requests
  for each row execute function amryn.touch_updated_at();

alter table public.data_requests enable row level security;
alter table public.data_requests force row level security;

-- A person may see and make their own requests, and nobody else''s. There is
-- deliberately no policy letting an organisation administrator read these: a
-- request to exercise a personal right is between the individual and the
-- responsible party, and an employer reading it would chill the exercise of it.
create policy data_requests_read_own on public.data_requests
  for select to authenticated
  using (user_id = auth.uid());

create policy data_requests_create_own on public.data_requests
  for insert to authenticated
  with check (user_id = auth.uid());

-- No update or delete policy at all. A request cannot be withdrawn by editing
-- it away, and its status is set by whoever handles it, outside this interface.

grant select, insert on public.data_requests to authenticated;

-- ── carrying consent through sign-up ──────────────────────────────────────
--
-- Consent is given on the sign-up form, but the profile row it belongs on may
-- not exist yet: where the project confirms addresses by email, the account is
-- created and the person disappears into their inbox for a while, and where
-- the trigger below could not be installed the profile is not written until
-- their first sign-in. Recording the acceptance in the account's own metadata
-- at the moment it is given, and copying it onto the profile whichever path
-- creates that profile, is what makes the record survive both gaps.
--
-- Both writers use coalesce on the existing timestamp, so a later acceptance
-- of a newer version is never overwritten by the one captured at sign-up.

create or replace function amryn.handle_new_user()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.user_profiles (
    id, email, full_name, avatar_url,
    terms_accepted_at, terms_version, privacy_accepted_at, privacy_version
  )
  values (
    new.id,
    new.email,
    coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'),
    new.raw_user_meta_data ->> 'avatar_url',
    (new.raw_user_meta_data ->> 'terms_accepted_at')::timestamptz,
    new.raw_user_meta_data ->> 'terms_version',
    (new.raw_user_meta_data ->> 'privacy_accepted_at')::timestamptz,
    new.raw_user_meta_data ->> 'privacy_version'
  )
  on conflict (id) do update
    set email = excluded.email,
        full_name = coalesce(public.user_profiles.full_name, excluded.full_name),
        terms_accepted_at = coalesce(public.user_profiles.terms_accepted_at, excluded.terms_accepted_at),
        terms_version = coalesce(public.user_profiles.terms_version, excluded.terms_version),
        privacy_accepted_at = coalesce(public.user_profiles.privacy_accepted_at, excluded.privacy_accepted_at),
        privacy_version = coalesce(public.user_profiles.privacy_version, excluded.privacy_version);
  return new;
end;
$$;

create or replace function public.ensure_user_profile()
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    return;
  end if;

  insert into public.user_profiles (
    id, email, full_name, avatar_url,
    terms_accepted_at, terms_version, privacy_accepted_at, privacy_version
  )
  select
    u.id,
    u.email,
    coalesce(u.raw_user_meta_data ->> 'full_name', u.raw_user_meta_data ->> 'name'),
    u.raw_user_meta_data ->> 'avatar_url',
    (u.raw_user_meta_data ->> 'terms_accepted_at')::timestamptz,
    u.raw_user_meta_data ->> 'terms_version',
    (u.raw_user_meta_data ->> 'privacy_accepted_at')::timestamptz,
    u.raw_user_meta_data ->> 'privacy_version'
  from auth.users u
  where u.id = uid
  on conflict (id) do update
    set email = excluded.email,
        full_name = coalesce(public.user_profiles.full_name, excluded.full_name),
        terms_accepted_at = coalesce(public.user_profiles.terms_accepted_at, excluded.terms_accepted_at),
        terms_version = coalesce(public.user_profiles.terms_version, excluded.terms_version),
        privacy_accepted_at = coalesce(public.user_profiles.privacy_accepted_at, excluded.privacy_accepted_at),
        privacy_version = coalesce(public.user_profiles.privacy_version, excluded.privacy_version);
end;
$$;

revoke all on function public.ensure_user_profile() from public, anon;
grant execute on function public.ensure_user_profile() to authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260831160000_14_security_events.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260831160000_14_security_events.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 14 — Security events that can be trusted
-- ═══════════════════════════════════════════════════════════════════════════
--
-- audit_logs has existed since migration 01 and had one writer: a change of
-- radar sector scope. Everything a security log exists for — who signed in,
-- who was invited, who joined, who took a copy of their own information — went
-- unrecorded, which made the privacy policy's promise that "sign-ins and
-- organisation changes are recorded" a sentence about something that was not
-- happening.
--
-- ── and the writes it did allow were not evidence ─────────────────────────
-- The insert policy was:
--
--   with check (organisation_id is null or amryn.is_member(organisation_id))
--
-- Any member could write any row: an action of their choosing, a summary of
-- their choosing, and — because actor_id was supplied by the caller — somebody
-- else's name on it. A log a subject can forge is not an audit log; it is a
-- table with an official-sounding name, and relying on it in an investigation
-- would be worse than having none.
--
-- So the row is written by a function that decides the two fields that matter,
-- and the direct insert is withdrawn.

create or replace function public.record_security_event(
  p_organisation_id uuid,
  p_action          text,
  p_entity_type     text default 'account',
  p_entity_id       text default null,
  p_summary         text default null,
  p_metadata        jsonb default '{}'::jsonb
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid uuid := auth.uid();
begin
  -- The actor is never taken from the caller. This is the whole point.
  if p_organisation_id is not null and not amryn.is_member(p_organisation_id) then
    raise exception 'not a member of that organisation' using errcode = '42501';
  end if;

  insert into public.audit_logs (
    organisation_id, actor_id, action, entity_type, entity_id, summary, metadata
  )
  values (
    p_organisation_id, uid, p_action, coalesce(p_entity_type, 'account'),
    p_entity_id, p_summary, coalesce(p_metadata, '{}'::jsonb)
  );
end;
$$;

comment on function public.record_security_event is
  'The only way the application writes an audit row. Sets actor_id from the session, so an entry cannot be attributed to somebody else.';

revoke all on function public.record_security_event(uuid, text, text, text, text, jsonb)
  from public, anon;
grant execute on function public.record_security_event(uuid, text, text, text, text, jsonb)
  to authenticated;

-- A sign-in has no organisation yet, and the person may belong to none. That
-- row is ours as responsible party rather than any employer's, which is also
-- why the read policy below leaves it invisible to organisation administrators.
create or replace function public.record_account_event(
  p_action  text,
  p_summary text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.audit_logs (organisation_id, actor_id, action, entity_type, summary)
  values (null, auth.uid(), p_action, 'account', p_summary);
end;
$$;

revoke all on function public.record_account_event(text, text) from public, anon;
-- anon may call this one: a failed sign-in has no session, and a log that
-- records only the attempts that succeeded is not a security log. The function
-- writes auth.uid(), which is null in that case, so an anonymous caller cannot
-- attribute an entry to anybody.
grant execute on function public.record_account_event(text, text) to authenticated, anon;

-- ── withdraw the forgeable path ──────────────────────────────────────────
--
-- Two changes, and the second is the one that makes the first survivable.
--
-- Dropping the policy is what removes the forgeable write. But audit_logs
-- carries FORCE row level security, which applies to the table's owner too —
-- and with no insert policy left, "everyone" includes the owner. Every
-- SECURITY DEFINER function that writes an audit row runs as that owner:
-- the two below, and create_organisation(), whose last statement records
-- 'organisation.created'. An error inside a function rolls the whole call
-- back, so dropping the policy alone would have broken organisation creation
-- outright — on the onboarding form, for every new customer.
--
-- On a local PostgreSQL this is invisible: there the owner is a superuser, and
-- a superuser bypasses row level security whether or not it is forced. On a
-- hosted Supabase project the postgres role is not a superuser, so it is
-- subject to the policies like anyone else. This is the third time that
-- difference has hidden a fault from the test suite; supabase/tests/17 now
-- reproduces it deliberately.
--
-- Lifting FORCE is the correct answer rather than a workaround. What must be
-- true of an append-only log is that the application cannot write to it
-- directly and can only read its own organisation's rows — and both survive:
-- the revoke below removes the write privilege from authenticated entirely,
-- which is a stronger guarantee than a policy, and audit_read still governs
-- every read, because a caller is never the owner. The only writers left are
-- the definer functions, which is what "the only way the application writes an
-- audit row" was meant to mean.
alter table public.audit_logs no force row level security;

drop policy if exists audit_append on public.audit_logs;
revoke insert, update, delete on public.audit_logs from authenticated, anon;

-- Reading is unchanged and deliberately narrow: an organisation administrator
-- with view_audit_log sees their own organisation's entries. Account-level
-- rows carry no organisation_id and so match no policy at all — nobody reads
-- those through the API, which is correct for a record of an individual's
-- sign-ins held by us rather than by their employer.

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260831180000_15_two_factor.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260831180000_15_two_factor.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 15 — Two-factor authentication
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Until now a stolen password was the whole attack. For a platform holding a
-- company's financial records, customer list and pipeline, that is the largest
-- single gap in the product.
--
-- Supabase issues and verifies the second factor itself, so none of the TOTP
-- machinery lives here. What lives here is the part an application must not
-- get wrong: making the requirement real.
--
-- ── why this is not only an application check ─────────────────────────────
-- The obvious implementation is a redirect: if the session has not completed
-- the challenge, send it to the verify page. That is worth doing and is not
-- enough. Every browser session also carries a key that speaks to PostgREST
-- directly, and a session that skipped the challenge is a perfectly valid
-- session as far as the database is concerned — so anyone willing to use the
-- API instead of the interface would read everything the redirect was hiding.
-- A second factor that can be walked around with curl is a checkbox, not a
-- control.
--
-- So the requirement is enforced where the data is. Supabase records the
-- authenticator assurance level in the token as `aal`: aal1 is a password,
-- aal2 is a password and a second factor. Every policy in this schema already
-- reaches the caller through amryn.is_member() or amryn.has_permission(), so
-- adding the condition to those two puts it in front of all 147 of them.

-- ── who has it turned on ──────────────────────────────────────────────────
--
-- Kept here rather than read from auth.mfa_factors, which belongs to another
-- role and may not be readable from this schema on every project. A guard that
-- cannot read its own input has to choose between failing open — which is not
-- a guard — and locking every customer out of their data over a missing grant.
-- This is our own table, and the application writes it in the same action that
-- verifies the factor.
alter table public.user_profiles
  add column mfa_enabled boolean not null default false,
  add column mfa_enabled_at timestamptz;

comment on column public.user_profiles.mfa_enabled is
  'Whether this person has a verified second factor. Set when enrolment is confirmed, cleared when the last factor is removed. The database refuses their data to a session that has not presented it.';

-- ── the guard ─────────────────────────────────────────────────────────────
create or replace function amryn.mfa_satisfied()
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select
    -- Presented the second factor on this session.
    coalesce(auth.jwt() ->> 'aal', 'aal1') = 'aal2'
    -- Or has none to present. Someone who has not turned it on is not asked
    -- for it, and neither is a background job, which carries no token at all:
    -- auth.uid() is null there, the row is not found, and the answer is true.
    or not exists (
      select 1
      from public.user_profiles p
      where p.id = auth.uid()
        and p.mfa_enabled
    );
$$;

comment on function amryn.mfa_satisfied is
  'False only for a session belonging to someone with two-factor turned on that has not completed the second step. Used by is_member() and has_permission(), so it applies to every policy without repeating it in each.';

-- ── applied to the two functions every policy goes through ────────────────
--
-- Deliberately not added to the policies one at a time. There are 147 of them;
-- a condition repeated 147 times is a condition that will be missing from the
-- 148th.

create or replace function amryn.is_member(p_org uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select amryn.mfa_satisfied() and exists (
    select 1
    from public.organisation_members m
    where m.organisation_id = p_org
      and m.user_id = auth.uid()
      and m.status = 'active'
  );
$$;

create or replace function amryn.has_permission(p_org uuid, p_permission text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  with member as (
    select m.id, m.role
    from public.organisation_members m
    where m.organisation_id = p_org
      and m.user_id = auth.uid()
      and m.status = 'active'
    limit 1
  ),
  override as (
    select o.granted
    from public.member_permission_overrides o
    join member on member.id = o.member_id
    where o.permission_key = p_permission
    limit 1
  ),
  role_default as (
    select true as granted
    from public.role_permissions rp
    join member on member.role = rp.role
    where rp.permission_key = p_permission
    limit 1
  )
  select amryn.mfa_satisfied() and coalesce(
    (select granted from override),
    (select granted from role_default),
    false
  );
$$;

-- member_role() is deliberately left alone. It answers "what is this person's
-- role", which the interface needs in order to render the page that explains
-- they must complete the second step — and it returns a label, never data.

-- ── recovery codes ────────────────────────────────────────────────────────
--
-- The failure mode of two-factor authentication is not an attacker; it is a
-- lost phone. Without a way back, turning it on is a way to lose an account,
-- and the people most likely to turn it on are the ones with the most to lose.
--
-- Ten single-use codes, stored as SHA-256 hashes for the same reason passwords
-- are: a database that can produce the codes is a database that can bypass the
-- factor. Redeeming one is not a sign-in — it removes the factor, and the
-- person is asked to enrol again. So the two things needed to get back in are
-- the password and a code, which is still two factors.

create table public.mfa_recovery_codes (
  id         uuid primary key default gen_random_uuid(),
  user_id    uuid not null references auth.users (id) on delete cascade,
  code_hash  text not null,
  used_at    timestamptz,
  created_at timestamptz not null default now(),
  unique (user_id, code_hash)
);

create index mfa_recovery_codes_user on public.mfa_recovery_codes (user_id)
  where used_at is null;

alter table public.mfa_recovery_codes enable row level security;

-- No force: the definer functions below are the only writers, exactly as with
-- audit_logs. See migration 14 for why forcing it would refuse them too.

-- A person may see that they have codes, and how many are left. The hash is
-- readable in the sense that any column of a visible row is, which is why it
-- is a hash: reading it yields nothing usable. Nobody sees anybody else's.
create policy mfa_recovery_read_own on public.mfa_recovery_codes
  for select to authenticated
  using (user_id = auth.uid());

-- No insert, update or delete policy at all. Codes are issued and spent by the
-- functions below, so a caller cannot mint themselves a code, and cannot
-- un-spend one.
grant select on public.mfa_recovery_codes to authenticated;
revoke insert, update, delete on public.mfa_recovery_codes from authenticated, anon;

/**
 * Replaces this person's recovery codes with the ones given.
 *
 * Takes hashes, never codes: the plaintext is generated in the application,
 * shown once, and never sent to the database. Replacing rather than adding,
 * because a fresh set has to invalidate the old one — otherwise a code from a
 * printout two years ago still works.
 */
create or replace function public.replace_recovery_codes(p_hashes text[])
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid uuid := auth.uid();
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  if array_length(p_hashes, 1) is null or array_length(p_hashes, 1) > 20 then
    raise exception 'expected between 1 and 20 recovery codes' using errcode = '22023';
  end if;

  delete from public.mfa_recovery_codes where user_id = uid;

  insert into public.mfa_recovery_codes (user_id, code_hash)
  select uid, hash from unnest(p_hashes) as hash;
end;
$$;

revoke all on function public.replace_recovery_codes(text[]) from public, anon;
grant execute on function public.replace_recovery_codes(text[]) to authenticated;

/**
 * Spends a recovery code, if it is one of this person's unused ones.
 *
 * Returns whether it was accepted. The update is the check — a single
 * statement that matches only an unused code and marks it used in the same
 * breath, so two simultaneous attempts with the same code cannot both succeed.
 */
create or replace function public.redeem_recovery_code(p_hash text)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  uid     uuid := auth.uid();
  spent   uuid;
begin
  if uid is null then
    raise exception 'authentication required' using errcode = '42501';
  end if;

  update public.mfa_recovery_codes
     set used_at = now()
   where user_id = uid
     and code_hash = p_hash
     and used_at is null
  returning id into spent;

  if spent is null then
    return false;
  end if;

  -- The code is spent and the factor is about to be removed by the caller,
  -- which holds the credentials to do it. Clearing the flag here keeps the
  -- two in step: a profile that still said mfa_enabled with no factor left
  -- would lock the account out of its own data with nothing able to satisfy
  -- the guard.
  update public.user_profiles
     set mfa_enabled = false, mfa_enabled_at = null
   where id = uid;

  return true;
end;
$$;

revoke all on function public.redeem_recovery_code(text) from public, anon;
grant execute on function public.redeem_recovery_code(text) to authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260901090000_16_subscription_entitlements.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260901090000_16_subscription_entitlements.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 16 — Subscription plans, entitlements and lapsed-account writes
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Migration 01 gave every organisation a `subscriptions` row carrying a plan
-- name and three numbers. Nothing read the plan. What a tier actually included
-- lived in a constant array on the billing page, and what a tier permitted
-- lived nowhere at all — an organisation whose subscription was cancelled a
-- year ago kept full use of the platform, because no code ever asked.
--
-- This migration supplies the two halves that were missing:
--
--   1. A catalogue. What each tier costs and what it includes are rows, so the
--      pricing page, the entitlement check and the payment webhook read one
--      answer. Changing what Growth includes is an update, not a deployment.
--
--   2. Enforcement. A subscription that has lapsed stops write access to the
--      business data, in the database, for every caller — including one
--      holding a valid token and talking to PostgREST directly rather than to
--      our pages.
--
-- ── why writes and not reads ──────────────────────────────────────────────
-- The blunt version of this is to refuse a lapsed organisation everything.
-- That is wrong on two counts. Commercially, a customer who cannot see the
-- invoice cannot pay it. Legally, POPIA s23 gives the data subject a right of
-- access that does not lapse when a card expires — locking someone out of
-- their own records to collect a debt would be the platform withholding
-- personal information it holds on request.
--
-- So a lapsed organisation keeps reading its own data, keeps its billing page,
-- keeps its export and deletion requests — and cannot add to, change or
-- destroy the business records until the subscription is current again.

-- ═══════════════════════════════════════════════════════════════════════════
-- 1. The catalogue
-- ═══════════════════════════════════════════════════════════════════════════

create table public.subscription_plans (
  plan                 public.subscription_plan primary key,
  name                 text    not null,
  tagline              text    not null,
  -- Rand, in cents. Null where the price is negotiated rather than published.
  price_cents_monthly  integer check (price_cents_monthly is null or price_cents_monthly >= 0),
  price_cents_annual   integer check (price_cents_annual is null or price_cents_annual >= 0),
  currency_code        char(3) not null default 'ZAR',
  -- The defaults a new subscription on this tier is opened with. The
  -- subscription row remains the effective state: an Enterprise contract is
  -- negotiated, and negotiating it must not require a catalogue edit that
  -- would move every other Enterprise customer with it.
  seats                integer not null default 3  check (seats > 0),
  -- Null is no limit. It has to be nullable for the same reason `included`
  -- and `limit_value` are separate columns below: unlimited and not-sold are
  -- different answers, and one number cannot carry both.
  data_source_limit    integer check (data_source_limit is null or data_source_limit >= 0),
  ai_credits_monthly   integer not null default 500 check (ai_credits_monthly >= 0),
  trial_days           integer not null default 30 check (trial_days >= 0),
  -- Enterprise is a conversation, not a checkout button.
  contact_sales        boolean not null default false,
  is_public            boolean not null default true,
  sort_order           integer not null default 0,
  created_at           timestamptz not null default now(),
  updated_at           timestamptz not null default now()
);

comment on table public.subscription_plans is
  'What each tier costs and what a subscription on it is opened with. Read by the pricing page, the billing page and the payment webhook, so the three cannot disagree.';

create trigger subscription_plans_touch
  before update on public.subscription_plans
  for each row execute function amryn.touch_updated_at();

insert into public.subscription_plans
