-- ═══════════════════════════════════════════════════════════════════════════
-- 3. What the subscription now has to record
-- ═══════════════════════════════════════════════════════════════════════════
--
-- There is no payment gateway. Customers pay by electronic transfer against a
-- reference, email the proof, and an operator issues an activation link. That
-- is a deliberate choice and not a placeholder: it needs no card processing
-- agreement, no gateway account, no secret in the deployment, and it matches
-- how South African business-to-business software of this size is actually
-- bought. The columns below record the outcome of that process, whoever
-- eventually performs it — a gateway added later writes the same fields.

-- Null is no limit, matching the catalogue. It was not null with a default of
-- two, which left no way to express the unlimited sources Professional is sold
-- with other than a large number that would eventually be reached.
alter table public.subscriptions
  alter column data_source_limit drop not null;

alter table public.subscriptions
  add column cancel_at_period_end boolean not null default false,
  add column cancelled_at         timestamptz,
  -- A payment that has not landed yet is not the same as a refusal to pay.
  -- Transfers between South African banks still take a day, and a customer who
  -- has paid should not lose the platform while the money is in flight. Set
  -- when the period lapses; cleared when an activation is redeemed.
  add column grace_until          timestamptz,
  add column last_payment_at      timestamptz,
  add column activated_at         timestamptz,
  add column activated_by         uuid references auth.users (id) on delete set null;

comment on column public.subscriptions.grace_until is
  'How long an unpaid period is tolerated before writes are refused. Null when the subscription is not in arrears.';

-- Bring the existing rows in line with the catalogue they were opened against.
-- Every organisation created before this migration is on Starter's defaults
-- already; this makes that a fact rather than a coincidence of two numbers
-- that happened to be typed the same.
update public.subscriptions s
   set price_cents_monthly = coalesce(p.price_cents_monthly, s.price_cents_monthly)
  from public.subscription_plans p
 where p.plan = s.plan
   and s.price_cents_monthly is distinct from coalesce(p.price_cents_monthly, s.price_cents_monthly);

-- ═══════════════════════════════════════════════════════════════════════════
-- 4. Paying by transfer, and being activated
-- ═══════════════════════════════════════════════════════════════════════════
--
-- The sequence, and where each step is recorded:
--
--   1. The customer chooses a plan and a term.       request_subscription()
--      They are given a reference to quote on the transfer.
--   2. They pay, and email the proof.                (outside the platform)
--   3. An operator confirms the money arrived.       issue_activation()
--      That mints a one-time link and returns it to be sent to the customer.
--   4. The customer opens the link.                  redeem_activation()
--      The plan is applied and the period starts from that moment.
--
-- Step 3 is the control. Nothing a customer can do — not the request, not the
-- proof they attach, not any field they can write — moves a subscription to
-- active. The platform never takes the customer's word for a payment, which is
-- the same rule a gateway integration would follow when it refuses to trust
-- the browser and waits for the webhook.

create table public.subscription_activations (
  id              uuid primary key default gen_random_uuid(),
  organisation_id uuid not null references public.organisations (id) on delete cascade,
  plan            public.subscription_plan not null,
  -- One month or twelve. Stored rather than derived so a change to the
  -- catalogue's annual price cannot retrospectively alter what was invoiced.
  term_months     integer not null default 1 check (term_months in (1, 12)),
  amount_cents    integer not null check (amount_cents >= 0),
  currency_code   char(3) not null default 'ZAR',
  -- What the customer quotes on the transfer, and what the operator matches
  -- the proof against. Unique, and generated rather than chosen.
  reference       text not null unique,

  state           text not null default 'awaiting_payment'
                    check (state in ('awaiting_payment', 'payment_confirmed', 'activated', 'cancelled', 'expired')),

  requested_by    uuid references auth.users (id) on delete set null,
  requested_at    timestamptz not null default now(),

  -- Set at step 3. Never the link itself: only a SHA-256 hash is stored, so a
  -- leaked backup activates nothing. The raw token exists once, in the
  -- response to the operator who will send it on. Same rule as invitations.
  token_hash      text unique,
  confirmed_by    uuid references auth.users (id) on delete set null,
  confirmed_at    timestamptz,
  payment_note    text,
  expires_at      timestamptz,

  activated_at    timestamptz,
  activated_by    uuid references auth.users (id) on delete set null,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- The states are not independent of the columns that record them.
  constraint confirmed_carries_a_token check (
    state = 'awaiting_payment' or state = 'cancelled' or token_hash is not null
  ),
  constraint activated_carries_a_time check (
    (state = 'activated') = (activated_at is not null)
  )
);

comment on table public.subscription_activations is
  'One row per attempt to buy or renew a subscription: what was asked for, what reference was quoted, who confirmed the money arrived, and when the customer redeemed the link. The billing history a dispute is answered from.';

-- One open request per organisation. A partial index rather than a plain
-- constraint, so the same organisation can request again after cancelling,
-- letting a request expire, or completing one.
create unique index subscription_activations_open
  on public.subscription_activations (organisation_id)
  where state in ('awaiting_payment', 'payment_confirmed');

create index subscription_activations_org_idx
  on public.subscription_activations (organisation_id, requested_at desc);

create trigger subscription_activations_touch
  before update on public.subscription_activations
  for each row execute function amryn.touch_updated_at();

-- ═══════════════════════════════════════════════════════════════════════════
-- 5. Reading an entitlement
-- ═══════════════════════════════════════════════════════════════════════════

-- Is this organisation's subscription in a state that permits work?
--
-- Split out from the entitlement question because the two fail differently: a
-- missing entitlement is an upgrade, an inactive subscription is a payment.
create or replace function amryn.subscription_current(org uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select
       case s.status
         when 'active'    then true
         -- A trial is a subscription until the day it says it is not.
         when 'trialing'  then coalesce(s.trial_ends_at, s.current_period_end) > now()
         -- In arrears, inside the grace period we allowed for it.
         when 'past_due'  then coalesce(s.grace_until, s.current_period_end + interval '7 days') > now()
         when 'cancelled' then false
         else false
       end
     from public.subscriptions s
     where s.organisation_id = org),
    -- No subscription row is not a free pass. Every organisation is created
    -- with one; an organisation without one is a broken record, and the safe
    -- reading of a broken billing record is "not paid".
    false);
$$;

comment on function amryn.subscription_current is
  'Whether the organisation may currently be worked in. Reads are never gated on this — see the header of migration 16.';

-- Does the organisation''s plan include this?
--
-- Note what is *not* here: the subscription''s status. A cancelled Professional
-- customer still has the Professional feature set — they simply cannot write.
-- Conflating the two would mean a lapsed account silently losing pages as well
-- as write access, and being told the wrong thing about why.
create or replace function amryn.has_entitlement(org uuid, key text)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select coalesce(
    (select pe.included
       from public.subscriptions s
       join public.plan_entitlements pe
         on pe.plan = s.plan and pe.entitlement_key = key
      where s.organisation_id = org),
    false);
$$;

-- The number attached to a quota, or null for no limit.
--
-- The subscription row wins over the catalogue where it carries its own
-- column, because that is where a negotiated contract is recorded. The
-- catalogue is what a tier opens with, not a ceiling it can never exceed.
create or replace function amryn.entitlement_limit(org uuid, key text)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select case key
    when 'seats'        then s.seats
    when 'data_sources' then s.data_source_limit
    when 'ai_credits'   then s.ai_credits_monthly
    else pe.limit_value
  end
  from public.subscriptions s
  left join public.plan_entitlements pe
    on pe.plan = s.plan and pe.entitlement_key = key
  where s.organisation_id = org;
$$;

-- One round trip for the whole picture, which is what a page render needs.
create view public.organisation_entitlements
with (security_invoker = true) as
select
  s.organisation_id,
  e.key            as entitlement_key,
  e.category,
  e.name,
  e.description,
  e.kind,
  e.sort_order,
  coalesce(pe.included, false) as included,
  case e.key
    when 'seats'        then s.seats
    when 'data_sources' then s.data_source_limit
    when 'ai_credits'   then s.ai_credits_monthly
    else pe.limit_value
  end              as limit_value
from public.subscriptions s
cross join public.entitlements e
left join public.plan_entitlements pe
  on pe.plan = s.plan and pe.entitlement_key = e.key;

comment on view public.organisation_entitlements is
  'Every entitlement resolved for every organisation the caller can see. security_invoker, so Row Level Security on subscriptions decides which organisations that is.';

-- ═══════════════════════════════════════════════════════════════════════════
-- 6. Refusing writes on a lapsed subscription
-- ═══════════════════════════════════════════════════════════════════════════
--
-- ── why a trigger and not a policy ────────────────────────────────────────
-- The policy version of this means appending a condition to the `with check`
-- of every write policy in the schema — around ninety of them, each edited by
-- hand, with no way to assert afterwards that none was missed. Worse, the
-- obvious shortcut of folding the condition into amryn.has_permission() would
-- catch reads too: several select policies are written against a manage_
-- permission, so a lapsed customer would lose sight of their own invoices,
-- which is the one thing they must be able to see.
--
-- A trigger separates the two cleanly. It fires on writes and never on reads,
-- it attaches by iterating the catalogue rather than by being remembered, and
-- it is one function to read when someone asks what the rule is.

create or replace function amryn.refuse_lapsed_write()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  org uuid;
begin
  -- The service role and the owner carry no `sub` claim: a webhook applying a
  -- payment, a scheduled job and a migration must all keep working, and it is
  -- specifically a payment that has to get through to end the lapse.
  if coalesce(nullif(current_setting('request.jwt.claim.sub', true), ''),
              nullif(auth.jwt() ->> 'sub', '')) is null then
    return coalesce(new, old);
  end if;

  org := case tg_op when 'DELETE' then old.organisation_id else new.organisation_id end;
  if org is null then
    return coalesce(new, old);
  end if;

  if not amryn.subscription_current(org) then
    raise exception
      'This organisation''s subscription is not active, so its records cannot be changed. Reading, exporting and billing are unaffected.'
      using errcode = 'check_violation',
            hint = 'Settle the subscription on the billing page to resume.';
  end if;

  return coalesce(new, old);
end $$;

comment on function amryn.refuse_lapsed_write is
  'Refuses changes to business records while a subscription is lapsed. Reads, billing and data-rights records are exempt — see migration 16 header.';

-- Which tables it guards.
--
-- Everything owned by an organisation, except:
--   billing              a customer who cannot pay cannot recover, and the
--                        activation that ends the lapse is itself a write
--   audit                the record of what happened must not have a gap
--   membership           removing a person's access must always be possible
--
-- The POPIA machinery is absent from the list for a better reason than
-- exemption: none of it is organisation-scoped. A data request belongs to the
-- person who made it and consent is columns on user_profiles and
-- organisations, so the loop below — which selects on organisation_id — never
-- reaches any of them. The right of access keeps working for the same reason
-- reads do, not because somebody remembered to name it here.
do $$
declare
  t text;
  exempt constant text[] := array[
    'subscriptions', 'billing_records', 'subscription_activations',
    'audit_logs',
    'organisation_members', 'member_permission_overrides',
    'organisation_invitations'
  ];
begin
  for t in
    select c.relname
      from pg_class c
      join pg_namespace n on n.oid = c.relnamespace
      join pg_attribute a on a.attrelid = c.oid and a.attname = 'organisation_id'
     where n.nspname = 'public'
       and c.relkind = 'r'
       and not a.attisdropped
       and c.relname <> all (exempt)
     order by c.relname
  loop
    execute format(
      'create trigger %I before insert or update or delete on public.%I '
      || 'for each row execute function amryn.refuse_lapsed_write()',
      left('zz_subscription_' || t, 63), t);
  end loop;
end $$;

-- ═══════════════════════════════════════════════════════════════════════════
-- 7. Moving a subscription, from one place
-- ═══════════════════════════════════════════════════════════════════════════

-- Puts an organisation on a plan and copies the catalogue's opening figures.
--
-- Definer, and deliberately not callable by a signed-in user. This is the only
-- statement in the schema that makes a subscription active, so it is reached
-- through redeem_activation() or by an operator holding the service role, and
-- never by posting to an endpoint.
create or replace function public.apply_subscription_plan(
  p_organisation uuid,
  p_plan         public.subscription_plan,
  p_status       public.subscription_status default null,
  p_period_start timestamptz default null,
  p_period_end   timestamptz default null
)
returns public.subscriptions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  catalogue public.subscription_plans;
  updated     public.subscriptions;
  -- Not named `status`: PL/pgSQL refuses a bare name that matches both a
  -- variable and a column of a table in the statement, and `subscriptions`
  -- has one.
  next_status public.subscription_status;
begin
  select * into catalogue from public.subscription_plans where plan = p_plan;
  if not found then
    raise exception 'no such plan: %', p_plan using errcode = '22023';
  end if;

  select coalesce(p_status, s.status) into next_status
    from public.subscriptions s where s.organisation_id = p_organisation;

  update public.subscriptions s
     set plan                 = p_plan,
         status               = coalesce(p_status, s.status),
         -- Seats can be negotiated above the catalogue, and a plan change
         -- never silently takes them away. Reducing someone's seat count is a
         -- decision for a person, not a side effect of applying a tier.
         seats                = greatest(catalogue.seats, s.seats),
         data_source_limit    = catalogue.data_source_limit,
         ai_credits_monthly   = catalogue.ai_credits_monthly,
         price_cents_monthly  = coalesce(catalogue.price_cents_monthly, s.price_cents_monthly),
         currency_code        = catalogue.currency_code,
         current_period_start = coalesce(p_period_start, s.current_period_start),
         current_period_end   = coalesce(p_period_end, s.current_period_end),
         -- Becoming active ends the arrears and the trial in one step.
         grace_until          = case when next_status = 'active' then null else s.grace_until end,
         trial_ends_at        = case when next_status = 'active' then null else s.trial_ends_at end,
         cancelled_at         = case when next_status = 'cancelled'
                                     then coalesce(s.cancelled_at, now()) else null end,
         activated_at         = case when next_status = 'active'
                                     then now() else s.activated_at end
   where s.organisation_id = p_organisation
  returning * into updated;

  if not found then
    raise exception 'organisation % has no subscription', p_organisation
      using errcode = 'P0002';
  end if;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)
  values
    (p_organisation, auth.uid(), 'subscription.plan_applied', 'subscription', updated.id::text,
     catalogue.name,
     jsonb_build_object('plan', p_plan, 'status', updated.status));

  return updated;
end $$;

revoke all on function public.apply_subscription_plan(uuid, public.subscription_plan, public.subscription_status, timestamptz, timestamptz) from public, anon, authenticated;

-- ── step 1: the customer asks ─────────────────────────────────────────────
--
-- Returns the reference to quote on the transfer. Deliberately says nothing
-- about the subscription itself: asking does not change what the organisation
-- currently has, and a request left unpaid must not remove anything either.
create or replace function public.request_subscription(
  p_plan        public.subscription_plan,
  p_term_months integer default 1
)
returns public.subscription_activations
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  catalogue public.subscription_plans;
  org       uuid;
  amount    integer;
  created   public.subscription_activations;
begin
  if auth.uid() is null then
    raise exception 'not signed in' using errcode = '28000';
  end if;
  if p_term_months not in (1, 12) then
    raise exception 'a subscription is bought by the month or by the year'
      using errcode = '22023';
  end if;

  -- The organisation is taken from the caller's own membership rather than
  -- from an argument, so nobody can open a request against a company they
  -- happen to know the identifier of.
  select m.organisation_id into org
    from public.organisation_members m
   where m.user_id = auth.uid()
     and m.status = 'active'
     and amryn.has_permission(m.organisation_id, 'manage_billing')
   order by m.joined_at
   limit 1;

  if org is null then
    raise exception 'only someone who manages billing can request a subscription'
      using errcode = '42501';
  end if;

  select * into catalogue from public.subscription_plans where plan = p_plan;
  if not found then
    raise exception 'no such plan: %', p_plan using errcode = '22023';
  end if;
  if catalogue.contact_sales then
    raise exception 'the % plan is arranged with us directly', catalogue.name
      using errcode = '22023',
            hint = 'Email the team and we will put the agreement together.';
  end if;

  amount := case when p_term_months = 12
                 then coalesce(catalogue.price_cents_annual, catalogue.price_cents_monthly * 12)
                 else catalogue.price_cents_monthly end;
  if amount is null then
    raise exception 'the % plan has no published price', catalogue.name
      using errcode = '22023';
  end if;

  -- Supersede whatever was open. Someone who changes their mind before paying
  -- should not have to ask an operator to clear the old request first.
  update public.subscription_activations
     set state = 'cancelled'
   where organisation_id = org
     and state in ('awaiting_payment', 'payment_confirmed');

  insert into public.subscription_activations
    (organisation_id, plan, term_months, amount_cents, currency_code, reference, requested_by)
  values
    (org, p_plan, p_term_months, amount, catalogue.currency_code,
     -- Short enough to be typed into a banking app's reference field, which is
     -- commonly twenty characters, and long enough not to collide.
     'AMR-' || upper(encode(gen_random_bytes(4), 'hex')),
     auth.uid())
  returning * into created;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)
  values
    (org, auth.uid(), 'subscription.requested', 'subscription_activation', created.id::text,
     catalogue.name,
     jsonb_build_object('plan', p_plan, 'term_months', p_term_months, 'reference', created.reference));

  return created;
end $$;

-- ── step 3: an operator confirms the money arrived ────────────────────────
--
-- Takes the hash, not the token. The link is generated by the application,
-- shown once to the operator who will send it, and never stored anywhere it
-- could be read back — the same treatment an invitation gets.
--
-- Revoked from every signed-in role. Confirming a payment is an operator
-- action carried out with the service role; a customer with manage_billing
-- must not be able to confirm their own transfer.
create or replace function public.issue_activation(
  p_activation uuid,
  p_token_hash text,
  p_confirmed_by uuid default null,
  p_note       text default null,
  p_valid_for  interval default interval '14 days'
)
returns public.subscription_activations
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  updated public.subscription_activations;
begin
  update public.subscription_activations a
     set state        = 'payment_confirmed',
         token_hash   = p_token_hash,
         confirmed_by = p_confirmed_by,
         confirmed_at = now(),
         payment_note = p_note,
         expires_at   = now() + p_valid_for
   where a.id = p_activation
     and a.state = 'awaiting_payment'
  returning * into updated;

  if not found then
    raise exception 'no activation awaiting payment with id %', p_activation
      using errcode = 'P0002';
  end if;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)
  values
    (updated.organisation_id, p_confirmed_by, 'subscription.payment_confirmed',
     'subscription_activation', updated.id::text, updated.reference,
     jsonb_build_object('plan', updated.plan, 'amount_cents', updated.amount_cents));

  return updated;
end $$;

revoke all on function public.issue_activation(uuid, text, uuid, text, interval) from public, anon, authenticated;

-- ── what the activation page may say before anyone is signed in ───────────
--
-- Possession of the link is the whole authorisation, so this returns only what
-- the page needs to render: which organisation, which plan, and whether the
-- link is still good. Not the amount, not the reference, not who paid.
create or replace function public.activation_preview(p_token text)
returns table (
  organisation_name text,
  plan              public.subscription_plan,
  plan_name         text,
  term_months       integer,
  state             text
)
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  hashed text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');
  record_ record;
begin
  select a.*, o.name as org_name, p.name as tier_name
    into record_
    from public.subscription_activations a
    join public.organisations o on o.id = a.organisation_id
    join public.subscription_plans p on p.plan = a.plan
   where a.token_hash = hashed;

  if record_.id is null then
    return query select null::text, null::public.subscription_plan, null::text, null::integer, 'unknown'::text;
    return;
  end if;

  return query select
    record_.org_name::text,
    record_.plan,
    record_.tier_name::text,
    record_.term_months,
    case
      when record_.state = 'activated' then 'already_used'
      when record_.state <> 'payment_confirmed' then 'unavailable'
      when record_.expires_at is not null and record_.expires_at < now() then 'expired'
      else 'ready'
    end::text;
end $$;

-- ── step 4: the customer redeems the link ─────────────────────────────────
--
-- The period runs from redemption rather than from confirmation, so a link
-- sent on a Friday and opened on a Monday does not cost the customer a
-- weekend. The activation is marked used in the same transaction that makes
-- the subscription active, so a link cannot be redeemed twice.
create or replace function public.redeem_activation(p_token text)
returns public.subscriptions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  hashed  text := encode(digest(coalesce(p_token, ''), 'sha256'), 'hex');
  claim   public.subscription_activations;
  result  public.subscriptions;
begin
  -- for update, so two clicks on the same link race for the row rather than
  -- both reading it as unused.
  select * into claim
    from public.subscription_activations
   where token_hash = hashed
   for update;

  if claim.id is null then
    raise exception 'this activation link is not recognised' using errcode = '22023';
  end if;
  if claim.state = 'activated' then
    raise exception 'this activation link has already been used' using errcode = '22023';
  end if;
  if claim.state <> 'payment_confirmed' then
    raise exception 'this activation link is not ready to be used' using errcode = '22023';
  end if;
  if claim.expires_at is not null and claim.expires_at < now() then
    update public.subscription_activations set state = 'expired' where id = claim.id;
    raise exception 'this activation link has expired' using errcode = '22023',
      hint = 'Ask us for a new one; the payment is still on record.';
  end if;

  result := public.apply_subscription_plan(
    claim.organisation_id,
    claim.plan,
    'active',
    now(),
    now() + make_interval(months => claim.term_months));

  update public.subscriptions
     set last_payment_at = now(),
         activated_by    = auth.uid()
   where organisation_id = claim.organisation_id
  returning * into result;

  update public.subscription_activations
     set state = 'activated', activated_at = now(), activated_by = auth.uid()
   where id = claim.id;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary, metadata)
  values
    (claim.organisation_id, auth.uid(), 'subscription.activated',
     'subscription_activation', claim.id::text, claim.reference,
     jsonb_build_object('plan', claim.plan, 'term_months', claim.term_months));

  return result;
end $$;

-- ── who may see an activation record ──────────────────────────────────────
alter table public.subscription_activations enable row level security;

-- Readable by whoever manages billing, so the customer can see the reference
-- to pay against and what has been confirmed.
create policy subscription_activations_read on public.subscription_activations
  for select to authenticated
  using (amryn.has_permission(organisation_id, 'manage_billing'));

-- No write policy, and the grant is revoked as well. Every write goes through
-- one of the definer functions above, which is what keeps the confirmation
-- step out of the customer's hands: a policy alone would let anyone with
-- manage_billing set state = 'activated' on their own row, because Row Level
-- Security decides rows, not columns.
--
-- Deliberately not forced: the definer functions run as this table's owner,
-- and forcing it would refuse them along with everyone else. The revoked grant
-- is the stronger control here and is unaffected either way — the same
-- reasoning, and the same exception, as audit_logs and mfa_recovery_codes.
revoke insert, update, delete on public.subscription_activations from authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 8. Who may read the catalogue
-- ═══════════════════════════════════════════════════════════════════════════

alter table public.subscription_plans  enable row level security;
alter table public.subscription_plans  force row level security;
alter table public.entitlements        enable row level security;
alter table public.entitlements        force row level security;
alter table public.plan_entitlements   enable row level security;
alter table public.plan_entitlements   force row level security;

-- The catalogue is the price list. It is on the marketing site, so treating it
-- as a secret from a signed-in customer would be theatre.
--
-- `to public` rather than `to authenticated` because forcing row level
-- security applies to the table's owner too, and the definer functions above
-- read these rows as the owner. A policy naming only `authenticated` would
-- leave apply_subscription_plan() reading an empty catalogue and reporting
-- "no such plan" for a tier that is sitting right there. The grant, not the
-- policy, is what keeps anonymous callers out: migration 09 grants these
-- tables to `authenticated` alone, and `anon` holds nothing.
create policy subscription_plans_read on public.subscription_plans
  for select to public using (true);

create policy entitlements_read on public.entitlements
  for select to public using (true);

create policy plan_entitlements_read on public.plan_entitlements
  for select to public using (true);

-- Nobody signed in changes the price list. It changes by migration, or by an
-- operator holding the service role.
revoke insert, update, delete on public.subscription_plans from authenticated;
revoke insert, update, delete on public.entitlements from authenticated;
revoke insert, update, delete on public.plan_entitlements from authenticated;

grant select on public.organisation_entitlements to authenticated;

-- ═══════════════════════════════════════════════════════════════════════════
-- 9. Privileges for the role that does the operator's work
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Found while writing the confirmation step, and older than this migration.
--
-- Migration 09 established default privileges so that a table added by a later
-- migration is reachable by `authenticated` — the snapshot problem, fixed for
-- one role. `service_role` has exactly the same problem and was not covered:
-- Supabase grants it the public schema once, at project creation, and that
-- grant likewise says nothing about tables that do not exist yet. Every table
-- added since migration 09 — rate limits, data requests, and now these — was
-- therefore invisible to the one client that is supposed to be able to reach
-- everything, and would have failed the first time an operator tool touched
-- one, reported as a missing table rather than as a missing privilege.
--
-- Row Level Security is not weakened by any of this: service_role bypasses it
-- by design, which is why the key never reaches a browser.
grant all on all tables in schema public to service_role;
grant all on all sequences in schema public to service_role;

alter default privileges in schema public
  grant all on tables to service_role;

alter default privileges in schema public
  grant all on sequences to service_role;

-- The two functions the operator holds alone. Revoked from every signed-in
-- role above; granted here to the one role that is meant to have them, because
-- `revoke ... from public` took the default away from service_role as well.
grant execute on function public.apply_subscription_plan(uuid, public.subscription_plan, public.subscription_status, timestamptz, timestamptz) to service_role;
grant execute on function public.issue_activation(uuid, text, uuid, text, interval) to service_role;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260901120000_17_onboarding.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260901120000_17_onboarding.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 17 — Intelligence onboarding
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Creating an organisation takes four fields and thirty seconds. What the
-- platform needs in order to say anything useful about a business takes rather
-- more: its shape, what it is trying to achieve, which systems hold its
-- numbers, and who it competes with. Until now none of that was ever asked,
-- so a new customer arrived at a Command Centre with nothing in it and no path
-- from there to something worth looking at.
--
-- Seven steps ask for it. This migration is what makes them resumable.
--
-- ── why a record and not a wizard ─────────────────────────────────────────
-- The obvious implementation keeps the answers in the browser until the last
-- step and writes everything at the end. That fails the way real onboarding
-- actually goes: it is done over several sittings, by more than one person,
-- and half of it is delegated ("ask the accountant which system that is").
-- Anything held client-side is lost by then.
--
-- So each step writes as it is answered, to the real tables — a branch entered
-- in step two is a branch, not a draft — and this record tracks only which
-- steps have been answered, which were skipped, and where to resume.

create table public.onboarding_progress (
  organisation_id uuid primary key references public.organisations (id) on delete cascade,

  -- Where "continue" goes.
  current_step    text not null default 'identity',
  completed_steps text[] not null default '{}',
  -- Skipping is a first-class answer, not an absence of one. A business with
  -- one site should not be made to invent a structure, and the review step has
  -- to be able to tell "not applicable" from "not yet done".
  skipped_steps   text[] not null default '{}',

  -- What was said that has no table of its own — how the business describes
  -- itself, roughly how large it is, which of its systems are on paper. Kept
  -- as a document because the questions will change and a column per question
  -- would mean a migration each time somebody rewords one.
  answers         jsonb not null default '{}'::jsonb,

  started_at      timestamptz not null default now(),
  completed_at    timestamptz,
  -- When the twin was first built from the answers. Separate from completion:
  -- somebody can finish the questions and not press the button.
  initialised_at  timestamptz,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- A misspelled step would otherwise sit in the array for ever, never
  -- matching, and the customer would be asked the same question at every
  -- sitting with no error anywhere to explain it.
  constraint steps_are_known check (
    current_step = any (array['identity','structure','objectives','systems','data','market','review'])
    and completed_steps <@ array['identity','structure','objectives','systems','data','market','review']
    and skipped_steps   <@ array['identity','structure','objectives','systems','data','market','review']
  ),
  -- A step cannot be both answered and skipped. Without this the review page
  -- has two contradictory sources for the same question.
  constraint not_both_done_and_skipped check (
    not (completed_steps && skipped_steps)
  )
);

comment on table public.onboarding_progress is
  'Which of the seven onboarding steps an organisation has answered, skipped, and where to resume. The answers themselves go to the real tables; only what has no table of its own is kept here.';

create trigger onboarding_progress_touch
  before update on public.onboarding_progress
  for each row execute function amryn.touch_updated_at();

alter table public.onboarding_progress enable row level security;
alter table public.onboarding_progress force row level security;

-- Every member can see how far setup has got — a colleague who lands on a half
-- empty Command Centre deserves to know why rather than assume it is broken.
create policy onboarding_progress_read on public.onboarding_progress
  for select to authenticated
  using (amryn.is_member(organisation_id));

create policy onboarding_progress_write on public.onboarding_progress
  for all to authenticated
  using (amryn.has_permission(organisation_id, 'manage_organisation'))
  with check (amryn.has_permission(organisation_id, 'manage_organisation'));

-- ── the guard from migration 16 does not reach this table ─────────────────
--
-- refuse_lapsed_write() was attached by iterating the catalogue at the moment
-- migration 16 ran. That is a snapshot, and this table did not exist yet — so
-- it carries no trigger, and neither will anything added after it unless
-- somebody remembers.
--
-- Here that is the right answer and is stated rather than inherited: setting
-- up is how a trial becomes a customer, and an organisation whose trial ran
-- out mid-onboarding must be able to finish and then pay. Test 19 asserts that
-- every other table with an organisation_id either carries the guard or is on
-- the exemption list, so the next table added is a failing test rather than a
-- silent gap.

-- ── opening the record ────────────────────────────────────────────────────
--
-- Definer, because the first caller is the person who has just created the
-- organisation and the row has to exist before anything can be saved against
-- it. Idempotent, so a refresh or a second tab costs nothing.
create or replace function public.ensure_onboarding(p_organisation uuid)
returns public.onboarding_progress
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  result public.onboarding_progress;
begin
  if not amryn.is_member(p_organisation) then
    raise exception 'not a member of that organisation' using errcode = '42501';
  end if;

  insert into public.onboarding_progress (organisation_id)
  values (p_organisation)
  on conflict (organisation_id) do nothing;

  select * into result from public.onboarding_progress
   where organisation_id = p_organisation;

  return result;
end $$;

-- ── finishing ─────────────────────────────────────────────────────────────
--
-- One statement, so that "the questions are answered" and "the twin has been
-- built" cannot disagree, and so the audit entry is written in the same
-- transaction as the thing it records.
create or replace function public.complete_onboarding(p_organisation uuid)
returns public.onboarding_progress
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  result public.onboarding_progress;
begin
  if not amryn.has_permission(p_organisation, 'manage_organisation') then
    raise exception 'only an administrator can finish setting up' using errcode = '42501';
  end if;

  update public.onboarding_progress
     set completed_at   = coalesce(completed_at, now()),
         initialised_at = coalesce(initialised_at, now()),
         current_step   = 'review'
   where organisation_id = p_organisation
  returning * into result;

  if not found then
    raise exception 'that organisation has not started setting up' using errcode = 'P0002';
  end if;

  insert into public.audit_logs
    (organisation_id, actor_id, action, entity_type, entity_id, summary)
  values
    (p_organisation, auth.uid(), 'onboarding.completed', 'organisation',
     p_organisation::text, 'Setup finished and the twin initialised');

  return result;
end $$;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260902130000_18_stock_control.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260902130000_18_stock_control.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 18 — Advanced Inventory Control
-- ═══════════════════════════════════════════════════════════════════════════
--
-- The inventory module was built against the second Excel workbook and read a
-- fixed dataset. Every screen worked, every calculation was right, and none of
-- it was anybody's stock: a real organisation opening Advanced Inventory
-- Control was shown a demonstration pharmacy's shelves. The module was
-- recently changed to say "not connected" instead, which was honest and not a
-- product. This is the table behind it.
--
-- ── the shape follows the workbook, because the workbook is the product ───
-- SETTINGS holds who is auditing what, on which shift; AUDIT LOG holds one row
-- per stock line. That is a session and its lines, so it is two tables rather
-- than one — and the second table is what makes a history possible. An audit
-- in March and an audit in June are two rows in `stock_audits`, and "what did
-- the shelves look like at year end" becomes answerable instead of being
-- overwritten.
--
-- ── what is deliberately not here ─────────────────────────────────────────
-- Compliance profiles stay in code. They encode what a sector's regulator
-- requires — SAHPRA retention, disposal evidence, who signs an audit off —
-- and a change to one should arrive as a reviewed diff, not as somebody
-- editing a text field on a Tuesday. `complianceProfile()` already falls back
-- to the general profile for an id it does not know, so adding a fourth is a
-- code change with no migration.

-- ── the vocabulary ────────────────────────────────────────────────────────
--
-- Snake case, not the workbook's display strings. The six actions are labels
-- an operator reads — "Marked Down / Clearance" — and rewording a label should
-- not be a schema change. The display strings live in the engine, where they
-- belong, and the mapping is one table in src/lib/inventory/mapping.ts.
create type public.stock_action as enum (
  'pending_review',
  'left_on_shelf',
  'removed_from_shelf',
  'returned_to_supplier',
  'marked_down',
  'destroyed'
);

create type public.stock_audit_status as enum ('draft', 'in_progress', 'complete');

-- ── the session ───────────────────────────────────────────────────────────

create table public.stock_audits (
  id                    uuid primary key default gen_random_uuid(),
  organisation_id       uuid not null references public.organisations (id) on delete cascade,
  -- Which site was walked. Null for an organisation that does not separate
  -- them, which is the single-shop case and must stay easy.
  branch_id             uuid references public.branches (id) on delete set null,

  -- SETTINGS!B4–B7. Kept as text rather than as references to people: the
  -- person who walked the shelves is often not a platform user, and an audit
  -- that cannot record a stocktaker because they have no login is an audit
  -- nobody does.
  site_name             text not null,
  auditor_name          text not null default '',
  responsible_name      text not null default '',
  shift                 text not null default '',

  -- Resolved in code against COMPLIANCE_PROFILES; an unknown id falls back to
  -- the general profile rather than failing, so a profile removed from the
  -- code does not strand an audit.
  compliance_profile_id text not null default 'general-inventory',

  audit_date            date not null default current_date,
  status                public.stock_audit_status not null default 'draft',

  created_by            uuid references auth.users (id) on delete set null,
  completed_at          timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),

  -- A completed audit is one with a completion time, and an incomplete one is
  -- not. Without this the report can be generated from a session somebody is
  -- still halfway through, and dated as though it were finished.
  constraint complete_carries_a_time check (
    (status = 'complete') = (completed_at is not null)
  )
);

comment on table public.stock_audits is
  'One stocktake: who walked which site, on what date, against which sector profile. The lines are in stock_items.';

create index stock_audits_org_idx on public.stock_audits (organisation_id, audit_date desc);

create trigger stock_audits_touch
  before update on public.stock_audits
  for each row execute function amryn.touch_updated_at();

-- ── the lines ─────────────────────────────────────────────────────────────

create table public.stock_items (
  id              uuid primary key default gen_random_uuid(),
  organisation_id uuid not null references public.organisations (id) on delete cascade,
  audit_id        uuid not null references public.stock_audits (id) on delete cascade,

  -- AUDIT LOG!B–H.
  product_name    text not null,
  sku             text not null default '',
  batch_number    text not null default '',
  department      text not null default '',
  location        text not null default '',
  qty             integer not null default 0 check (qty >= 0),
  expiry_date     date not null,

  -- AUDIT LOG!I–N. `action` is nullable-by-default rather than null: a line
  -- nobody has looked at is 'pending_review', which is a state the workbook
  -- names, and the dormancy rules test against it. Null would make every rule
  -- carry a coalesce.
  action          public.stock_action not null default 'pending_review',
  actioned_by     text not null default '',
  actioned_on     date,
  notes           text not null default '',

  -- AUDIT LOG!O — the auditor's tick that this line has been dealt with.
  verified        boolean not null default false,

  -- Cents, like every other money column here, so the report can state
  -- capital at risk without a float. Null where the cost is not known, which
  -- is common and must not read as zero.
  unit_cost_cents bigint check (unit_cost_cents is null or unit_cost_cents >= 0),

  -- Set where a sales feed shows the item moving. Overrides the workbook's
  -- inference that an item left on the shelf and not near expiry is dormant —
  -- an inference it makes because it cannot see turnover.
  has_movement    boolean,

  -- The order the lines were counted in. The report prints them as numbered
  -- rows and an auditor reads down the shelf, so the order is information.
  position        integer not null default 0,

  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),

  -- An action that has been taken has a date. Recording one without the other
  -- is how a disposal ends up undocumented, which is the specific thing the
  -- insurance and regulator notes on the report depend on.
  constraint actioned_lines_carry_a_date check (
    action = 'pending_review' or actioned_on is not null
  )
);

comment on table public.stock_items is
  'One line of a stocktake. Expiry status, dormancy and value at risk are computed by the engine from these columns rather than stored, so a figure can never disagree with its own formula.';

create index stock_items_audit_idx on public.stock_items (audit_id, position);
create index stock_items_org_idx on public.stock_items (organisation_id);
-- Expiry is what every report section sorts and filters on.
create index stock_items_expiry_idx on public.stock_items (organisation_id, expiry_date);

create trigger stock_items_touch
  before update on public.stock_items
  for each row execute function amryn.touch_updated_at();

-- ── the permission ────────────────────────────────────────────────────────
--
-- A new key rather than reusing import_data. Importing a spreadsheet and
-- marking a batch destroyed are different acts with different consequences,
-- and the second is the one a regulator asks about. Naming it separately means
-- it can be granted separately.
insert into public.permissions (key, category, description) values
  ('manage_inventory', 'Operations', 'Record stocktakes, action stock lines and import stock');

do $$
declare
  r public.org_role;
begin
  -- Everyone who can already see operational data, plus the analyst who does
  -- the importing. Deliberately not the viewer: actioning a line is a
  -- decision about stock, not a way of reading about it.
  foreach r in array array[
    'super_admin','org_admin','executive','regional_manager',
    'branch_manager','department_manager','analyst'
  ]::public.org_role[]
  loop
    insert into public.role_permissions (role, permission_key)
    values (r, 'manage_inventory')
    on conflict do nothing;
  end loop;
end $$;

-- ── who may read and write them ───────────────────────────────────────────

alter table public.stock_audits enable row level security;
alter table public.stock_audits force row level security;
alter table public.stock_items  enable row level security;
alter table public.stock_items  force row level security;

create policy stock_audits_read on public.stock_audits
  for select to authenticated
  using (amryn.has_permission(organisation_id, 'view_operations_data'));

create policy stock_audits_write on public.stock_audits
  for all to authenticated
  using (amryn.has_permission(organisation_id, 'manage_inventory'))
  with check (amryn.has_permission(organisation_id, 'manage_inventory'));

create policy stock_items_read on public.stock_items
  for select to authenticated
  using (amryn.has_permission(organisation_id, 'view_operations_data'));

create policy stock_items_write on public.stock_items
  for all to authenticated
  using (amryn.has_permission(organisation_id, 'manage_inventory'))
  with check (amryn.has_permission(organisation_id, 'manage_inventory'));

-- ── the lapsed-subscription guard ─────────────────────────────────────────
--
-- Attached by hand, and that is the point. Migration 16 attached it by
-- iterating the catalogue at the moment it ran, which is a snapshot: a table
-- added afterwards carries no trigger and nothing about writing this migration
-- would say so. Test 19 asserts the whole list, so leaving these two out is a
-- failing test rather than a silent gap — which is exactly what it was written
-- to catch.
--
-- Stock is business data, so it is guarded rather than exempt: an organisation
-- whose subscription has lapsed keeps reading its stocktakes and its report,
-- and cannot record new ones.
create trigger zz_subscription_stock_audits
  before insert or update or delete on public.stock_audits
  for each row execute function amryn.refuse_lapsed_write();

create trigger zz_subscription_stock_items
  before insert or update or delete on public.stock_items
  for each row execute function amryn.refuse_lapsed_write();

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260905060000_19_extension_schema_resolution.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260905060000_19_extension_schema_resolution.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 19 — where the database looks for pgcrypto
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Five functions were dead on the hosted database. Not slow, not wrong —
-- dead, every call, for every caller:
--
--   request_subscription   42883  function gen_random_bytes(integer) does not exist
--   activation_preview     42883  function digest(text, unknown) does not exist
--   redeem_activation      42883  function digest(text, unknown) does not exist
--   invitation_preview     42883  function digest(text, unknown) does not exist
--   accept_invitation      42883  function digest(text, unknown) does not exist
--
-- Between them that is the whole of the paid journey and the whole of the team
-- journey: nobody could take out a subscription, nobody could be handed an
-- activation link after paying by EFT, and nobody could be invited into an
-- organisation. The screens were all built and all correct; the call at the
-- bottom of each one raised before it did anything.
--
-- ── why it was invisible ──────────────────────────────────────────────────
--
-- Migration 01 asks for the extension without saying where:
--
--     create extension if not exists "pgcrypto";
--
-- On a plain PostgreSQL instance that installs it into `public`, which is on
-- the search_path, and everything resolves. On Supabase pgcrypto is already
-- installed — into `extensions` — so `if not exists` does nothing at all and
-- the functions stay where Supabase put them.
--
-- Each of the five then pins `search_path = public, pg_temp`, correctly, so
-- that a caller cannot shadow what a SECURITY DEFINER function resolves. That
-- pin excludes `extensions`. The symbols are present in the database and
-- unreachable from inside the function.
--
-- CI runs the SQL suite against a plain PostgreSQL, where the extension lands
-- in `public` and all five pass. The failure exists only on the layout nobody
-- tested, which is the layout in production. Test 22 now recreates the hosted
-- arrangement, so this cannot come back silently.
--
-- ── the fix ───────────────────────────────────────────────────────────────
--
-- Add `extensions` to the pin rather than schema-qualifying each call site.
-- Qualifying would hardcode one of the two layouts and break the other; naming
-- both schemas is correct on both, because PostgreSQL ignores an entry in
-- search_path that does not exist. Nothing untrusted can write to `extensions`
-- — it is owned by the database owner and neither anon nor authenticated holds
-- CREATE on it — so widening the pin by that one schema gives up none of what
-- the pin is for.
--
-- ALTER rather than CREATE OR REPLACE: the bodies are right and were never the
-- problem, and restating them here would leave two copies to keep in step.

alter function public.request_subscription(public.subscription_plan, integer)
  set search_path = public, extensions, pg_temp;
alter function public.activation_preview(text)
  set search_path = public, extensions, pg_temp;
alter function public.redeem_activation(text)
  set search_path = public, extensions, pg_temp;
alter function public.invitation_preview(text)
  set search_path = public, extensions, pg_temp;
alter function public.accept_invitation(text)
  set search_path = public, extensions, pg_temp;

-- ── prove it, here, rather than trusting the ALTERs ───────────────────────
--
-- The five above are the ones known to be broken. This resolves the symbols
-- the way those functions now resolve them and fails the migration if either
-- is still unreachable, so a database that would go on refusing every payment
-- and every invitation cannot record this migration as applied.
do $$
declare
  probe bytea;
begin
  perform set_config('search_path', 'public, extensions, pg_temp', true);
  probe := digest('resolution probe', 'sha256');
  probe := gen_random_bytes(4);
exception when undefined_function then
  raise exception
    'pgcrypto is not reachable from public, extensions, pg_temp — subscriptions, activations and invitations would still fail'
    using errcode = '42883';
end $$;

-- ── while here: the five trigger functions with no pin at all ─────────────
--
-- Found by the same sweep. These are SECURITY INVOKER, so an unpinned path is
-- not the privilege escalation it would be above — a caller who shadowed a
-- name would only be shadowing it for themselves. It is still the one rule the
-- rest of the schema keeps without exception, and a trigger that decides
-- whether a branch belongs to your organisation is not where to start making
-- exceptions. Every object each of them touches is already schema-qualified,
-- so pinning changes no behaviour.

alter function amryn.assert_branch_region_same_org()     set search_path = public, pg_temp;
alter function amryn.assert_department_branch_same_org() set search_path = public, pg_temp;
alter function amryn.assert_health_weights_sum()         set search_path = public, pg_temp;
alter function amryn.derive_risk_severity()              set search_path = public, pg_temp;
alter function amryn.touch_updated_at()                  set search_path = public, pg_temp;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260905070000_20_rls_initplan.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260905070000_20_rls_initplan.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 20 — evaluate auth.uid() once per query, not once per row
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Twelve policies name auth.uid() directly. PostgreSQL treats that as a
-- per-row expression and calls it again for every row it examines, so reading
-- a thousand notifications reads the JWT a thousand times. Wrapping it in a
-- scalar subquery makes it an InitPlan: computed once, before the scan, and
-- compared against as a constant.
--
--   using (user_id = auth.uid())            → one call per row
--   using (user_id = (select auth.uid()))   → one call per query
--
-- The two are equivalent. auth.uid() is STABLE — by definition it cannot
-- change within a statement — so a single evaluation is not an approximation
-- of the per-row one, it is the same answer arrived at once. Nothing about who
-- can see what changes here, which is the only reason this is worth doing at
-- all: an optimisation that alters a tenancy boundary is not an optimisation.
--
-- Left alone deliberately: amryn.is_member(organisation_id) and
-- amryn.has_permission(organisation_id, ...). They read auth.uid() too, but
-- they take a column as an argument, so they genuinely do depend on the row
-- and cannot be hoisted out of the scan. Wrapping those would change what they
-- are asked, not when.
--
-- Policies are dropped and recreated rather than altered, because ALTER POLICY
-- cannot change a policy's command or roles and restating the whole thing
-- makes the diff readable. Each is recreated with the same command, the same
-- roles and the same predicate, differing only in the parenthesised select.

-- ── user_profiles ─────────────────────────────────────────────────────────

drop policy user_profiles_read on public.user_profiles;
create policy user_profiles_read on public.user_profiles
  for select to authenticated
  using (
    id = (select auth.uid())
    or exists (
      select 1
        from public.organisation_members me
        join public.organisation_members them
          on them.organisation_id = me.organisation_id
       where me.user_id = (select auth.uid())
         and me.status = 'active'
         and them.user_id = user_profiles.id
    )
  );

drop policy user_profiles_write on public.user_profiles;
create policy user_profiles_write on public.user_profiles
  for update to authenticated
  using (id = (select auth.uid()))
  with check (id = (select auth.uid()));

drop policy user_profiles_insert on public.user_profiles;
create policy user_profiles_insert on public.user_profiles
  for insert to authenticated
  with check (id = (select auth.uid()));

-- ── organisation_members ──────────────────────────────────────────────────
--
-- The first arm is what lets somebody see their own membership row in an
-- organisation they are not yet active in; is_member() would refuse it.

drop policy members_read on public.organisation_members;
create policy members_read on public.organisation_members
  for select to authenticated
  using (user_id = (select auth.uid()) or amryn.is_member(organisation_id));

-- ── opportunity_assignments ───────────────────────────────────────────────

drop policy opportunity_assignments_read on public.opportunity_assignments;
create policy opportunity_assignments_read on public.opportunity_assignments
  for select to authenticated
  using (
    assignee_id = (select auth.uid())
    or amryn.has_permission(organisation_id, 'view_opportunities')
  );

-- ── notifications ─────────────────────────────────────────────────────────
--
-- The table this matters most on: a notification list is read constantly and
-- is the one place a user routinely scans many of their own rows at once.

drop policy notifications_read on public.notifications;
create policy notifications_read on public.notifications
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy notifications_update on public.notifications;
create policy notifications_update on public.notifications
  for update to authenticated
  using (user_id = (select auth.uid()))
  with check (user_id = (select auth.uid()));

-- ── the assistant's own conversations ─────────────────────────────────────

drop policy ai_conversations_own on public.ai_conversations;
create policy ai_conversations_own on public.ai_conversations
  for all to authenticated
  using (user_id = (select auth.uid()) and amryn.is_member(organisation_id))
  with check (user_id = (select auth.uid()) and amryn.is_member(organisation_id));

drop policy ai_messages_own on public.ai_messages;
create policy ai_messages_own on public.ai_messages
  for all to authenticated
  using (
    amryn.is_member(organisation_id)
    and exists (
      select 1 from public.ai_conversations c
       where c.id = ai_messages.conversation_id
         and c.user_id = (select auth.uid())
    )
  )
  with check (
    amryn.is_member(organisation_id)
    and exists (
      select 1 from public.ai_conversations c
       where c.id = ai_messages.conversation_id
         and c.user_id = (select auth.uid())
    )
  );

-- ── POPIA requests and recovery codes ─────────────────────────────────────

drop policy data_requests_read_own on public.data_requests;
create policy data_requests_read_own on public.data_requests
  for select to authenticated
  using (user_id = (select auth.uid()));

drop policy data_requests_create_own on public.data_requests;
create policy data_requests_create_own on public.data_requests
  for insert to authenticated
  with check (user_id = (select auth.uid()));

drop policy mfa_recovery_read_own on public.mfa_recovery_codes;
create policy mfa_recovery_read_own on public.mfa_recovery_codes
  for select to authenticated
  using (user_id = (select auth.uid()));

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260905080000_21_revoke_unused_anon_grants.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260905080000_21_revoke_unused_anon_grants.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 21 — take back the anon grants nothing asked for
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Every SECURITY DEFINER function from migration 04 to migration 15 ends with
-- a line taking back what PostgreSQL grants by default:
--
--     revoke all on function public.accept_invitation(text) from public, anon;
--
-- Migrations 16 and 17 wrote nine such functions and remembered it twice.
-- The other five are reachable by anyone holding the publishable key, over
-- /rest/v1/rpc/, without signing in.
--
-- None of them is exploitable — each was probed on the live database as anon
-- and each refuses:
--
--     ensure_onboarding      42501  not a member of that organisation
--     complete_onboarding    42501  only an administrator can finish setting up
--     request_subscription   28000  not signed in
--     redeem_activation      requires auth.uid() to record who activated
--
-- So this changes no answer. It changes where the answer is decided: at the
-- grant, rather than eleven statements into a function body that had to be
-- read to know it was safe. Every one of these is called by the application
-- with a session — redeem_activation() through requireUser() in
-- features/billing/activate.ts — so nothing loses a caller it had.
--
-- The point is not this week's function bodies. It is that a guard added in
-- one place is one edit away from being removed, and the convention the rest
-- of the schema keeps means that edit cannot silently open a door.

-- Revoke then grant, both halves, as migration 11 does for accept_invitation.
-- The revoke alone would lock out the people these exist for: on a database
-- built from these migrations `authenticated` has no grant of its own on any
-- of the four and reaches them through the default PUBLIC one, so taking that
-- back takes their own access with it. The SQL suite caught exactly that —
-- test 19 could no longer buy a subscription.

revoke all on function public.ensure_onboarding(uuid) from public, anon;
grant execute on function public.ensure_onboarding(uuid) to authenticated;

revoke all on function public.complete_onboarding(uuid) from public, anon;
grant execute on function public.complete_onboarding(uuid) to authenticated;

revoke all on function public.request_subscription(public.subscription_plan, integer) from public, anon;
grant execute on function public.request_subscription(public.subscription_plan, integer) to authenticated;

revoke all on function public.redeem_activation(text) from public, anon;
grant execute on function public.redeem_activation(text) to authenticated;

-- ── the one that stays open, and why ──────────────────────────────────────
--
-- activation_preview() answers the page somebody lands on from the email
-- before they have signed in — "Amryn (Pty) Ltd, Professional, ready" — and
-- must keep answering it. Possession of the link is the whole authorisation,
-- which is why the function returns the organisation, the plan and the state
-- and not the amount, the reference, or who paid.
--
-- Revoked from PUBLIC and granted to anon deliberately, exactly as
-- invitation_preview() is: the two are the same shape and the same decision.
revoke all on function public.activation_preview(text) from public;
grant execute on function public.activation_preview(text) to anon, authenticated;

notify pgrst, 'reload schema';

-- ══════════════════════════════════════════════════════════════════════
-- 20260905190000_22_foreign_key_indexes.sql
-- ══════════════════════════════════════════════════════════════════════
do $setup$ begin raise notice 'applying 20260905190000_22_foreign_key_indexes.sql'; end $setup$;

-- ═══════════════════════════════════════════════════════════════════════════
-- Amryn™ AIGrowthIntelligence® Software
-- Migration 22 — an index on every foreign key
-- ═══════════════════════════════════════════════════════════════════════════
--
-- Seventy-four foreign keys had no index. PostgreSQL does not create one: a
-- foreign key constrains the child, and indexing it is left to whoever knows
-- how the data will be read.
--
-- Two things go wrong without them, and only one is about queries.
--
-- ── the one everybody thinks of ───────────────────────────────────────────
-- Every row-level security policy in this schema filters on organisation_id.
-- Ten tables carried that column as an unindexed foreign key, so every read
-- against them was a sequential scan filtered afterwards. That is invisible at
-- a few hundred rows and is exactly the shape of thing that becomes a support
-- ticket at a few hundred thousand.
--
-- ── the one that bites first ──────────────────────────────────────────────
-- Deleting a parent row makes PostgreSQL check every child table that
-- references it — to cascade, to null, or to refuse. Without an index that
-- check is a sequential scan of the child, per parent row deleted, whether or
-- not anybody ever queries by that column.
--
-- Most of these cascade from organisations. Deleting one customer's
-- organisation would have scanned every table in the schema, holding locks
-- throughout. The POPIA erasure path does exactly that, and it is the one
-- operation that must not time out halfway.
--
-- ── why all of them, rather than a chosen few ─────────────────────────────
-- Because the second reason applies to every foreign key regardless of query
-- patterns, and because choosing a subset means predicting which columns will
-- be filtered on later — a guess that reads as engineering judgement and is
-- not. The write cost is a few bytes per row per index on tables that are
-- currently small; the alternative is finding out which ones mattered from a
-- customer.
--
-- Single-column, and deliberately not composite. An index only serves a
-- foreign key's integrity check when the key's columns are a *prefix* of it,
-- so (organisation_id, branch_id) would serve the organisation_id key and do
-- nothing at all for the branch_id one.
--
-- `if not exists` throughout, so this is safe to re-run and safe on a database
-- where somebody has already added one by hand.

-- ── organisation_id: the column every RLS policy filters on ───────────────
--
-- These ten are the highest value in the file on both counts — the filter path
-- for every read, and the cascade path when an organisation is deleted.

create index if not exists ai_conversations_org_idx
  on public.ai_conversations (organisation_id);
create index if not exists ai_messages_org_idx
  on public.ai_messages (organisation_id);
create index if not exists goal_progress_org_idx
  on public.goal_progress (organisation_id);
create index if not exists market_sources_org_idx
  on public.market_sources (organisation_id);
create index if not exists member_permission_overrides_org_idx
  on public.member_permission_overrides (organisation_id);
create index if not exists notifications_org_idx
  on public.notifications (organisation_id);
create index if not exists opportunity_activities_org_idx
  on public.opportunity_activities (organisation_id);
create index if not exists opportunity_scores_org_idx
  on public.opportunity_scores (organisation_id);
create index if not exists risk_events_org_idx
  on public.risk_events (organisation_id);
create index if not exists strategic_initiatives_org_idx
  on public.strategic_initiatives (organisation_id);

-- ── where a record sits: region, branch, department ───────────────────────
--
-- The scoping columns. A regional manager's every query narrows by branch, and
-- closing a branch cascades through all of these.

create index if not exists ai_recommendations_branch_idx
  on public.ai_recommendations (branch_id);
create index if not exists alerts_branch_idx
  on public.alerts (branch_id);
create index if not exists alerts_department_idx
  on public.alerts (department_id);
create index if not exists branches_region_idx
  on public.branches (region_id);
create index if not exists business_events_branch_idx
  on public.business_events (branch_id);
create index if not exists business_events_department_idx
  on public.business_events (department_id);
create index if not exists business_health_scores_branch_idx
  on public.business_health_scores (branch_id);
create index if not exists business_insights_branch_idx
  on public.business_insights (branch_id);
create index if not exists departments_branch_idx
  on public.departments (branch_id);
create index if not exists financial_records_branch_idx
  on public.financial_records (branch_id);
create index if not exists financial_records_department_idx
  on public.financial_records (department_id);
create index if not exists goals_branch_idx
  on public.goals (branch_id);
create index if not exists goals_department_idx
  on public.goals (department_id);
-- Not metric_values_branch_idx: that name is taken by a partial composite,
-- (organisation_id, branch_id, period_start DESC) WHERE branch_id IS NOT NULL,
-- which serves the organisation_id key and does nothing for this one — wrong
-- leading column, and partial besides. `if not exists` matched the name and
-- skipped the index silently; test 23 is what noticed.
create index if not exists metric_values_branch_fk_idx
  on public.metric_values (branch_id);
create index if not exists metric_values_department_idx
  on public.metric_values (department_id);
create index if not exists operational_records_branch_idx
  on public.operational_records (branch_id);
create index if not exists operational_records_department_idx
  on public.operational_records (department_id);
create index if not exists opportunities_branch_idx
  on public.opportunities (branch_id);
create index if not exists risks_branch_idx
  on public.risks (branch_id);
create index if not exists sales_records_branch_idx
  on public.sales_records (branch_id);
